-- Prepared seven-language chocolate_truffles block; NOT executed.
-- Integrate inside one atomic15recipe lote04 transaction ONLY after all15ready,
-- CI/merge and observed deployed media hashes. Caller must set the batch gate.
DO $chocolate_truffles$
DECLARE
 j constant jsonb := $records$[{"id": "0f9407eb-d658-433d-9bff-477f17ab273f", "recipe_group_id": "b5dc3c62-05ba-4ce6-8748-39570d2271a9", "slug": "recetas-de-trufas-de-chocolate", "public_path": "/recetas-de-trufas-de-chocolate", "source_url": "https://manualdecocina.com/recetas-de-trufas-de-chocolate/", "language": "es", "title": "Trufas de chocolate negro propuestas con cacao", "excerpt": "Ganache de chocolate negro, nata y mantequilla con cacao fino: veinte piezas propuestas y tiempos completos de frío.", "summary": "Trufas propuestas de ganache con chocolate negro, nata pasteurizada, mantequilla y cacao natural. Se proponen 20 piezas individuales y 202 minutos completos, incluidos ambos periodos de frío; cantidades, firmeza y rendimiento pendientes de confirmación en cocina.", "category": "Postres", "category_slug": "postres", "difficulty": "Media", "course": "Postre", "cuisine": "Inspiración francesa", "prep_time_minutes": 30, "cook_time_minutes": 5, "total_time_minutes": 202, "servings": 20, "ingredients": [{"name": "chocolate negro en tableta para fundir, 70 % de cacao, sin relleno", "amount": "200", "unit": "g", "group": "Ganache"}, {"name": "nata líquida pasteurizada para montar, 36 % de grasa", "amount": "100", "unit": "g", "group": "Ganache"}, {"name": "mantequilla sin sal", "amount": "20", "unit": "g", "group": "Ganache"}, {"name": "cacao natural puro en polvo sin azúcar, para cobertura", "amount": "10", "unit": "g", "group": "Cobertura"}], "steps": [{"title": "Prepara y pesa", "content": "Lávate las manos y prepara báscula, cuchillo, cuenco resistente al calor, cazo pequeño, espátula, recipiente poco profundo con tapa y bandeja con papel de horno. Pesa 200 g de chocolate negro en tableta de 70 % de cacao, sin relleno ni sustituto de cobertura, y pícalo fino en el cuenco seco. Pesa 100 g de nata líquida pasteurizada para montar de 36 % de grasa, 20 g de mantequilla sin sal y 10 g de cacao natural puro sin azúcar. Corta la mantequilla en dados pequeños y deja ablandar unos 20 minutos; pesa y pica durante los primeros 5 de ese intervalo. Mantén la nata refrigerada hasta calentarla. No añadas azúcar, vainilla, licor, frutos secos ni más chocolate.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-01.webp", "image_alt": "Trufas de chocolate propuestas: Prepara y pesa"}, {"title": "Calienta la nata sin reducirla", "content": "Pon los 100 g de nata en el cazo y calienta a fuego medio-bajo, removiendo, unos 5 minutos hasta que salga vapor y aparezcan pequeñas burbujas en el borde. Retira antes de una ebullición intensa: se busca calentar, no reducir ni hervir varios minutos. Vierte toda la nata caliente sobre el chocolate picado, con cuidado de no quemarte. Si tarda más, añade el tiempo real; vigila el cazo durante todo el calentamiento.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-02.webp", "image_alt": "Trufas de chocolate propuestas: Calienta la nata sin reducirla"}, {"title": "Emulsiona con la mantequilla", "content": "Deja el chocolate cubierto por la nata unos 2 minutos sin tocar. Después remueve desde el centro con espátula unos 3 minutos, incorporando los 20 g de mantequilla blanda, hasta obtener una ganache uniforme, sin trozos visibles ni aceite separado. No batas para montar ni añadas líquido no pesado. Si quedan trozos, calienta el cuenco sobre agua apenas caliente sin que su base toque el agua, remueve suavemente y suma el tiempo adicional; evita que entre agua. Si no queda homogénea, revisa el tipo de chocolate y la temperatura antes de seguir.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-03.webp", "image_alt": "Trufas de chocolate propuestas: Emulsiona con la mantequilla"}, {"title": "Enfría la ganache tapada", "content": "Pasa toda la ganache a un recipiente poco profundo, tapa y refrigera a 4 °C o menos unos 120 minutos, hasta que esté firme pero se pueda sacar con cuchara. Enfría esta pequeña cantidad enseguida; no la dejes esperando templada fuera. Los perecederos deben refrigerarse dentro de 2 horas, o 1 hora por encima de 32 °C. Si está demasiado blanda, prolonga el frío y añade el tiempo real. La firmeza depende de marca, grasa y temperatura y está pendiente de confirmación en cocina.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-04.webp", "image_alt": "Trufas de chocolate propuestas: Enfría la ganache tapada"}, {"title": "Forma y cubre las trufas", "content": "Prepara manos y utensilios limpios y secos. Pesa la ganache fría real y divide entre 20 para obtener porciones semejantes; los 320 g iniciales de ganache sugerirían unos 16 g por centro, pero no son rendimiento final medido. Forma bolas ligeramente irregulares sin calentarlas mucho con las manos. Usa los 10 g de cacao reservados en un plato pequeño para cubrirlas con una capa fina, sin chocolate fundido adicional. Dedica unos 20 minutos. Si la ganache está demasiado dura, espera unos 5 minutos antes de formar y súmalos; si se ablanda, vuelve a enfriar y registra el tiempo. La estimación incluye todo el cacao pesado; si sobra, pesa el retenido antes de confirmar nutrición y no fuerces incorporarlo.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-05.webp", "image_alt": "Trufas de chocolate propuestas: Forma y cubre las trufas"}, {"title": "Reafirma en frío", "content": "Coloca todas las trufas en una sola capa sobre papel de horno dentro de un recipiente limpio, tapa y refrigera a 4 °C o menos unos 30 minutos, hasta que mantengan su forma. No congeles para abreviar el proceso ni añadas más cacao. Si necesitan más frío, suma el tiempo real. Se proponen veinte piezas, no un rendimiento probado; conserva el recipiente tapado hasta servir.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-06.webp", "image_alt": "Trufas de chocolate propuestas: Reafirma en frío"}, {"title": "Sirve y conserva", "content": "Dedica unos 2 minutos a servir solo las piezas necesarias; se propone 1 trufa por ración y veinte piezas. Los 330 g son la suma inicial, no peso final medido. El total propuesto es 202 minutos: ablandar y preparar 20, calentar 5, reposar y mezclar 5, primer frío 120, formar y cubrir 20, segundo frío 30 y servir 2. Cantidades, tiempos y porciones están pendientes de confirmación en cocina. Guarda tapadas a 4 °C o menos. Consumir en 24 horas es una propuesta de calidad no ensayada, no vida útil validada; no se fija congelación. No reutilices sobras del plato ni juzgues seguridad por olor; cuenta todo el tiempo fuera del frigorífico.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "image_alt": "Trufas de chocolate propuestas: Sirve y conserva"}], "nutrition": {"calories": 85.1, "protein_g": 1.0, "carbs_g": 5.0, "fat_g": 6.9, "saturated_fat_g": 4.1, "fiber_g": 1.3, "sugar_g": 2.6, "sodium_mg": 3.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy (abril de 2018)", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "chocolate negro en tableta para fundir, 70 % de cacao, sin relleno", "edible_grams": 200, "fdc_id": 170273, "fdc_description": "Chocolate, dark, 70-85% cacao solids", "per_100g": {"calories": 598, "protein_g": 7.79, "carbs_g": 45.9, "fat_g": 42.6, "saturated_fat_g": 24.5, "fiber_g": 10.9, "sugar_g": 24.0, "sodium_mg": 20.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170273/nutrients"}, {"ingredient": "nata líquida pasteurizada para montar, 36 % de grasa", "edible_grams": 100, "fdc_id": 170859, "fdc_description": "Cream, fluid, heavy whipping", "per_100g": {"calories": 340, "protein_g": 2.84, "carbs_g": 2.84, "fat_g": 36.1, "saturated_fat_g": 23.0, "fiber_g": 0.0, "sugar_g": 2.92, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170859/nutrients"}, {"ingredient": "mantequilla sin sal", "edible_grams": 20, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "cacao natural puro en polvo sin azúcar, para cobertura", "edible_grams": 10, "fdc_id": 169593, "fdc_description": "Cocoa, dry powder, unsweetened", "per_100g": {"calories": 228, "protein_g": 19.6, "carbs_g": 57.9, "fat_g": 13.7, "saturated_fat_g": 8.07, "fiber_g": 37.0, "sugar_g": 1.75, "sodium_mg": 21.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169593/nutrients"}], "serving_size": "Una trufa; 20 unidades propuestas", "method": "Suma de gramos por valores USDA por 100 g, dividida entre 20. Cuatro alimentos exactos y ocho nutrientes informados en todos; datos ausentes nunca inventados.", "note": "Estimación pendiente de confirmación, no análisis ni prueba de cocina. Los 330 g son peso inicial, no rendimiento final medido. Chocolate USDA genérico de 70–85 % de cacao, no análisis de una tableta concreta de 70 %. Nata para montar y mantequilla genéricas; marca, grasa y agua varían. Incluye los 10 g de cacao de cobertura completos; si sobra, pesa lo adherido antes de confirmar nutrición. No inventa pérdida por evaporación, restos en utensilios o absorción de cacao. No incluye chocolate de baño, alcohol, azúcar extra ni acompañamientos."}, "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "gallery": [{"url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "alt": "Veinte trufas pequeñas de chocolate negro, ligeramente irregulares y cubiertas con una fina capa de cacao marrón mate, sin adornos ni baño de chocolate"}], "published": false, "editorial_status": "draft", "keywords": ["trufas de chocolate", "ganache con cacao", "trufas sin alcohol añadido"], "notes": "Propuesta de trufas de ganache con chocolate negro, nata, mantequilla y cobertura fina de cacao, sin baño de chocolate ni alcohol añadido. El chocolate elegido es tableta lisa para fundir de 70 % de cacao; la ficha USDA representa el intervalo genérico 70–85 %, no un análisis de esa marca o porcentaje exacto. La nata debe ser líquida pasteurizada para montar de 36 % de grasa, no nata agria ni cobertura vegetal; la ficha USDA es genérica y la marca puede variar. Contiene leche; revisa etiquetas del chocolate, cacao y lácteos, incluida soja y trazas de frutos secos u otros alérgenos. No se garantiza ausencia de gluten, aptitud para alergias ni versión vegana. Cambiar chocolate, porcentaje de cacao, nata o mantequilla modifica firmeza y nutrición; requiere ajustar y recalcular, no sustituir sin más. Se incluye todo el cacao pesado como estimación; si parte queda en el plato, mide lo adherido antes de confirmar y no inventes absorción ni pérdidas. No se añaden azúcar, vainilla, licor, frutos secos o acompañamientos. Trabaja con utensilios secos, manipula nata caliente con cuidado y evita agua dentro de la ganache. Refrigera a 4 °C o menos dentro de 2 horas, o 1 hora por encima de 32 °C; cuenta tiempo acumulado fuera y no dejes la nata o ganache templada esperando. No se presenta como producto estable a temperatura ambiente. Las 24 horas propuestas son criterio de calidad no ensayado, no conservación validada. No se afirma prueba de cocina ni beneficio de salud.", "seo": {"title": "Trufas de chocolate negro con cacao paso a paso", "description": "Ganache de chocolate, nata y mantequilla: cantidades para veinte trufas propuestas, dos periodos de frío, cobertura fina y conservación.", "image_alt": "Veinte trufas pequeñas de chocolate negro, ligeramente irregulares y cubiertas con una fina capa de cacao marrón mate, sin adornos ni baño de chocolate", "image_variants": ["/recetas/recetas-de-trufas-de-chocolate/portada-1x1.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-4x3.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-16x9.webp"], "faq": [{"q": "¿Puedo usar chocolate con leche, blanco o chips?", "a": "No como sustitución directa. La propuesta usa tableta lisa de chocolate negro de 70 % de cacao; la relación con nata y mantequilla debe revisarse al cambiar chocolate. Los chips pueden contener ingredientes que alteran la fusión. El cálculo USDA es genérico de 70–85 %, no análisis de la marca elegida."}, {"q": "¿Qué hago si la ganache está demasiado blanda o dura?", "a": "Si está blanda, enfría más hasta poder porcionar y añade el tiempo real. Si está muy dura, deja templar brevemente antes de formar, sin exceder límites de conservación. Revisa marca, grasa y emulsión; no añadas cantidades improvisadas ni afirmes que esta textura está probada. Cuenta las pausas adicionales."}, {"q": "¿Cuánto tarda y cuánto se conserva?", "a": "Se proponen 202 minutos incluyendo preparación, calentamiento, reposo, dos periodos de frío, formado y servicio. Los tiempos adicionales se suman. Guarda a 4 °C o menos y refrigera dentro de 2 horas, o 1 hora por encima de 32 °C. Consumir en 24 horas es una propuesta de calidad no ensayada, no vida útil validada; no se garantiza almacenamiento a temperatura ambiente."}]}, "content_html": "<p>Trufas propuestas de ganache con chocolate negro, nata pasteurizada, mantequilla y cacao natural. Se proponen 20 piezas individuales y 202 minutos completos, incluidos ambos periodos de frío; cantidades, firmeza y rendimiento pendientes de confirmación en cocina.</p><p>Propuesta de trufas de ganache con chocolate negro, nata, mantequilla y cobertura fina de cacao, sin baño de chocolate ni alcohol añadido. El chocolate elegido es tableta lisa para fundir de 70 % de cacao; la ficha USDA representa el intervalo genérico 70–85 %, no un análisis de esa marca o porcentaje exacto. La nata debe ser líquida pasteurizada para montar de 36 % de grasa, no nata agria ni cobertura vegetal; la ficha USDA es genérica y la marca puede variar. Contiene leche; revisa etiquetas del chocolate, cacao y lácteos, incluida soja y trazas de frutos secos u otros alérgenos. No se garantiza ausencia de gluten, aptitud para alergias ni versión vegana. Cambiar chocolate, porcentaje de cacao, nata o mantequilla modifica firmeza y nutrición; requiere ajustar y recalcular, no sustituir sin más. Se incluye todo el cacao pesado como estimación; si parte queda en el plato, mide lo adherido antes de confirmar y no inventes absorción ni pérdidas. No se añaden azúcar, vainilla, licor, frutos secos o acompañamientos. Trabaja con utensilios secos, manipula nata caliente con cuidado y evita agua dentro de la ganache. Refrigera a 4 °C o menos dentro de 2 horas, o 1 hora por encima de 32 °C; cuenta tiempo acumulado fuera y no dejes la nata o ganache templada esperando. No se presenta como producto estable a temperatura ambiente. Las 24 horas propuestas son criterio de calidad no ensayado, no conservación validada. No se afirma prueba de cocina ni beneficio de salud.</p>"}, {"id": "ab3e8ba0-a246-5210-8596-f3103c01d9f1", "recipe_group_id": "b5dc3c62-05ba-4ce6-8748-39570d2271a9", "slug": "schokoladen-truffel-rezepte", "public_path": "/de/schokoladen-truffel-rezepte", "source_url": "https://manualdecocina.com/de/schokoladen-truffel-rezepte/", "language": "de", "title": "Vorschlag für dunkle Schokoladentrüffel mit Kakao", "excerpt": "Ganache aus dunkler Schokolade, Sahne und Butter mit dünner Kakaoschicht: zwanzig vorgeschlagene Stücke mit vollständigen Kühlzeiten.", "summary": "Vorgeschlagene Ganache-Trüffel aus dunkler Schokolade, pasteurisierter Sahne, Butter und natürlichem Kakao. Vorgesehen sind 20 einzelne Stücke und insgesamt 202 Minuten einschließlich beider Kühlphasen; Mengen, Festigkeit und Ausbeute sind noch in der Küche zu bestätigen.", "category": "Desserts", "category_slug": "postres", "difficulty": "Mittel", "course": "Dessert", "cuisine": "Französisch inspiriert", "prep_time_minutes": 30, "cook_time_minutes": 5, "total_time_minutes": 202, "servings": 20, "ingredients": [{"name": "ungefüllte dunkle Schokoladentafel zum Schmelzen, 70 % Kakao", "amount": "200", "unit": "g", "group": "Ganache"}, {"name": "pasteurisierte flüssige Schlagsahne, 36 % Fett", "amount": "100", "unit": "g", "group": "Ganache"}, {"name": "ungesalzene Butter", "amount": "20", "unit": "g", "group": "Ganache"}, {"name": "natürliches ungesüßtes Kakaopulver zum Wälzen", "amount": "10", "unit": "g", "group": "Überzug"}], "steps": [{"title": "Vorbereiten und abwiegen", "content": "Hände waschen und Waage, Messer, hitzefeste Schüssel, kleinen Topf, Spatel, flachen Behälter mit Deckel und mit Backpapier belegtes Blech bereitstellen. 200 g ungefüllte dunkle Schokoladentafel mit 70 % Kakao abwiegen, keine kakaohaltige Fettglasur, und fein in die trockene Schüssel hacken. 100 g pasteurisierte flüssige Schlagsahne mit 36 % Fett, 20 g ungesalzene Butter und 10 g natürliches ungesüßtes Kakaopulver wiegen. Butter klein würfeln und etwa 20 Minuten weich werden lassen; während der ersten 5 Minuten wiegen und hacken. Sahne bis zum Erwärmen gekühlt halten. Keinen Zucker, Vanille, Likör, Nüsse oder weitere Schokolade hinzufügen.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-01.webp", "image_alt": "Vorschlag für dunkle Schokoladentrüffel mit Kakao: Vorbereiten und abwiegen"}, {"title": "Sahne erwärmen, nicht reduzieren", "content": "100 g Sahne im kleinen Topf bei mittlerer bis niedriger Hitze unter Rühren etwa 5 Minuten erwärmen, bis Dampf und kleine Bläschen am Rand auftreten. Vor kräftigem Kochen vom Herd nehmen: Erwärmen ist das Ziel, nicht Reduzieren oder minutenlanges Kochen. Gesamte heiße Sahne vorsichtig über die gehackte Schokolade gießen, ohne sich zu verbrennen. Falls es länger dauert, tatsächliche Zeit addieren; Topf während des gesamten Erwärmens beobachten.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-02.webp", "image_alt": "Vorschlag für dunkle Schokoladentrüffel mit Kakao: Sahne erwärmen, nicht reduzieren"}, {"title": "Mit Butter emulgieren", "content": "Schokolade unter der Sahne etwa 2 Minuten unberührt ruhen lassen. Danach etwa 3 Minuten mit dem Spatel von der Mitte aus rühren und die 20 g weiche Butter einarbeiten, bis die Ganache gleichmäßig ist, ohne sichtbare Stücke oder abgesetztes Öl. Nicht aufschlagen oder ungewogene Flüssigkeit hinzufügen. Bei verbliebenen Stückchen die Schüssel vorsichtig über wenig heißem Wasser erwärmen, ohne dass ihr Boden das Wasser berührt, sanft rühren und Zusatzzeit addieren; kein Wasser eindringen lassen. Ist die Masse nicht homogen, Schokoladensorte und Temperatur prüfen, bevor es weitergeht.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-03.webp", "image_alt": "Vorschlag für dunkle Schokoladentrüffel mit Kakao: Mit Butter emulgieren"}, {"title": "Ganache zugedeckt kühlen", "content": "Gesamte Ganache in einen flachen Behälter geben, abdecken und bei höchstens 4 °C etwa 120 Minuten kühlen, bis sie fest, aber löffelbar ist. Die kleine Menge sofort kühlen, nicht lauwarm draußen warten lassen. Verderbliche Lebensmittel binnen 2 Stunden kühlen, über 32 °C binnen 1 Stunde. Ist sie zu weich, länger kühlen und tatsächliche Zeit addieren. Festigkeit hängt von Marke, Fett und Temperatur ab und ist noch in der Küche zu bestätigen.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-04.webp", "image_alt": "Vorschlag für dunkle Schokoladentrüffel mit Kakao: Ganache zugedeckt kühlen"}, {"title": "Trüffel formen und wälzen", "content": "Saubere trockene Hände und Geräte verwenden. Tatsächliche kalte Ganache wiegen und durch 20 teilen, um ähnliche Portionen zu bilden; die anfänglichen 320 g Ganache entsprächen etwa 16 g je Kern, sind aber keine gemessene Endausbeute. Leicht unregelmäßige Kugeln formen, ohne sie mit den Händen zu stark zu erwärmen. Die vorgesehenen 10 g Kakao in einem kleinen Teller für eine dünne Schicht nutzen, ohne zusätzliche geschmolzene Schokolade. Etwa 20 Minuten vorsehen. Bei zu harter Ganache vor dem Formen etwa 5 Minuten warten und addieren; wird sie weich, erneut kühlen und Zeit erfassen. Die Schätzung rechnet sämtlichen gewogenen Kakao ein; bei Resten vor Bestätigung der Nährwerte die haftende Menge wiegen und die Aufnahme nicht erzwingen.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-05.webp", "image_alt": "Vorschlag für dunkle Schokoladentrüffel mit Kakao: Trüffel formen und wälzen"}, {"title": "Im Kühlschrank festigen", "content": "Alle Trüffel einlagig auf Backpapier in einen sauberen Behälter legen, abdecken und bei höchstens 4 °C etwa 30 Minuten kühlen, bis sie ihre Form behalten. Nicht zum Beschleunigen einfrieren oder mehr Kakao hinzufügen. Nötige zusätzliche Kühlzeit addieren. Zwanzig Stücke sind vorgeschlagen, keine erprobte Ausbeute; bis zum Servieren zugedeckt halten.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-06.webp", "image_alt": "Vorschlag für dunkle Schokoladentrüffel mit Kakao: Im Kühlschrank festigen"}, {"title": "Servieren und lagern", "content": "Etwa 2 Minuten zum Servieren nur der benötigten Stücke vorsehen; vorgeschlagen sind 1 Trüffel je Portion und zwanzig Stücke. 330 g ist die Anfangssumme, kein gemessenes Endgewicht. Insgesamt sind 202 Minuten vorgesehen: Weichwerden und Vorbereitung 20, Erwärmen 5, Ruhen und Rühren 5, erste Kühlung 120, Formen und Wälzen 20, zweite Kühlung 30 und Servieren 2. Mengen, Zeiten und Portionen sind noch in der Küche zu bestätigen. Zugedeckt bei höchstens 4 °C lagern. Verzehr binnen 24 Stunden ist ein ungeprüfter Qualitätsvorschlag, keine validierte Haltbarkeit; keine Gefrierdauer festgelegt. Tellerreste nicht wiederverwenden, Sicherheit nicht nach Geruch beurteilen und gesamte Zeit außerhalb des Kühlschranks zählen.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "image_alt": "Vorschlag für dunkle Schokoladentrüffel mit Kakao: Servieren und lagern"}], "nutrition": {"calories": 85.1, "protein_g": 1.0, "carbs_g": 5.0, "fat_g": 6.9, "saturated_fat_g": 4.1, "fiber_g": 1.3, "sugar_g": 2.6, "sodium_mg": 3.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "ungefüllte dunkle Schokoladentafel zum Schmelzen, 70 % Kakao", "edible_grams": 200, "fdc_id": 170273, "fdc_description": "Chocolate, dark, 70-85% cacao solids", "per_100g": {"calories": 598, "protein_g": 7.79, "carbs_g": 45.9, "fat_g": 42.6, "saturated_fat_g": 24.5, "fiber_g": 10.9, "sugar_g": 24.0, "sodium_mg": 20.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170273/nutrients"}, {"ingredient": "pasteurisierte flüssige Schlagsahne, 36 % Fett", "edible_grams": 100, "fdc_id": 170859, "fdc_description": "Cream, fluid, heavy whipping", "per_100g": {"calories": 340, "protein_g": 2.84, "carbs_g": 2.84, "fat_g": 36.1, "saturated_fat_g": 23.0, "fiber_g": 0.0, "sugar_g": 2.92, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170859/nutrients"}, {"ingredient": "ungesalzene Butter", "edible_grams": 20, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "natürliches ungesüßtes Kakaopulver zum Wälzen", "edible_grams": 10, "fdc_id": 169593, "fdc_description": "Cocoa, dry powder, unsweetened", "per_100g": {"calories": 228, "protein_g": 19.6, "carbs_g": 57.9, "fat_g": 13.7, "saturated_fat_g": 8.07, "fiber_g": 37.0, "sugar_g": 1.75, "sodium_mg": 21.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169593/nutrients"}], "serving_size": "Ein Trüffel; 20 vorgeschlagene Stücke", "method": "Gramm mit USDA-Werten je 100 g multiplizieren, summieren und durch 20 teilen. Vier exakte Lebensmittel mit jeweils acht berichteten Nährwerten; fehlende Daten nie erfunden.", "note": "Noch zu bestätigende Schätzung, keine Analyse oder Küchenprüfung. 330 g ist Anfangsgewicht, keine gemessene Endausbeute. Allgemeine USDA-Schokolade mit 70–85 % Kakao, keine Analyse einer konkreten Tafel mit 70 %. Allgemeine Schlagsahne und Butter; Marke, Fett und Wasser variieren. Sämtliche 10 g Überzugskakao einbezogen; bei Resten haftenden Kakao vor Bestätigung der Nährwerte wiegen. Keine erfundenen Verluste durch Verdampfen, Geräteanhaftung oder Kakaoaufnahme. Schokoladenhülle, Alkohol, Zusatzzucker und Beilagen ausgeschlossen."}, "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "gallery": [{"url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "alt": "Zwanzig kleine leicht unregelmäßige dunkle Schokoladentrüffel mit dünnem mattbraunem Kakaoüberzug, ohne Dekoration oder Schokoladenhülle"}], "published": false, "editorial_status": "draft", "keywords": ["Schokoladentrüffel", "Ganache mit Kakao", "Trüffel ohne zugesetzten Alkohol"], "notes": "Vorschlag für Ganache-Trüffel aus dunkler Schokolade, Sahne und Butter mit dünner Kakaoschicht, ohne Schokoladenhülle oder zugesetzten Alkohol. Ungefüllte Tafel zum Schmelzen mit 70 % Kakao wählen; USDA beschreibt den allgemeinen Bereich 70–85 %, keine Analyse der Marke oder des genauen Prozentsatzes. Pasteurisierte flüssige Schlagsahne mit 36 % Fett verwenden, keine saure Sahne oder pflanzliche Schlagcreme; USDA ist allgemein und Marken variieren. Enthält Milch; Etiketten von Schokolade, Kakao und Milchprodukten einschließlich Soja und Nussspuren oder weiterer Allergene prüfen. Keine Garantie für Glutenfreiheit, Allergieverträglichkeit oder vegane Eignung. Andere Schokolade, Kakaoanteile, Sahne oder Butter verändern Festigkeit und Nährwerte; anpassen und neu berechnen. Gesamter gewogener Kakao wird geschätzt einbezogen; bei Tellerresten haftende Menge vor Bestätigung messen, keine Aufnahme oder Verluste erfinden. Kein zusätzlicher Zucker, Vanille, Likör, Nüsse oder Beilagen. Trockene Geräte nutzen, heiße Sahne vorsichtig handhaben und Wasser aus Ganache fernhalten. Binnen 2 Stunden bei höchstens 4 °C kühlen, über 32 °C binnen 1 Stunde; gesamte Zeit draußen zählen, Sahne und lauwarme Ganache nicht warten lassen. Kein bei Raumtemperatur haltbares Produkt behauptet. Vorgeschlagene 24 Stunden sind ungeprüftes Qualitätskriterium, keine validierte Lagerung. Keine Küchenprüfung oder Gesundheitswirkung behauptet.", "seo": {"title": "Dunkle Schokoladentrüffel mit Kakao: Schritt für Schritt", "description": "Ganache aus Schokolade, Sahne und Butter: Mengen für zwanzig vorgeschlagene Trüffel, zwei Kühlphasen, dünne Kakaoschicht und Lagerung.", "image_alt": "Zwanzig kleine leicht unregelmäßige dunkle Schokoladentrüffel mit dünnem mattbraunem Kakaoüberzug, ohne Dekoration oder Schokoladenhülle", "image_variants": ["/recetas/recetas-de-trufas-de-chocolate/portada-1x1.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-4x3.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-16x9.webp"], "faq": [{"q": "Kann ich Milchschokolade, weiße Schokolade oder Chips nehmen?", "a": "Nicht als direkten Ersatz. Vorgesehen ist eine ungefüllte dunkle Tafel mit 70 % Kakao; bei anderer Schokolade das Verhältnis zu Sahne und Butter prüfen. Chips können das Schmelzen beeinflussende Zutaten enthalten. USDA berechnet allgemein 70–85 %, keine Analyse der gewählten Marke."}, {"q": "Was tun bei zu weicher oder harter Ganache?", "a": "Weiche Ganache länger kühlen, bis sie portionierbar ist, und reale Zusatzzeit addieren. Sehr harte Masse vor Formen kurz weich werden lassen, Lagergrenzen beachten. Marke, Fett und Emulsion prüfen; keine ungewogenen Zusätze improvisieren oder diese Konsistenz als erprobt darstellen. Zusätzliche Pausen zählen."}, {"q": "Wie lange dauert es und wie wird gelagert?", "a": "Vorgesehen sind 202 Minuten einschließlich Vorbereitung, Erwärmen, Ruhe, beiden Kühlphasen, Formen und Servieren. Tatsächliche Zusatzzeiten addieren. Bei höchstens 4 °C halten und binnen 2 Stunden kühlen, über 32 °C binnen 1 Stunde. Verzehr binnen 24 Stunden ist ungeprüfter Qualitätsvorschlag, keine validierte Haltbarkeit; Raumtemperaturlagerung nicht garantiert."}]}, "content_html": "<p>Vorgeschlagene Ganache-Trüffel aus dunkler Schokolade, pasteurisierter Sahne, Butter und natürlichem Kakao. Vorgesehen sind 20 einzelne Stücke und insgesamt 202 Minuten einschließlich beider Kühlphasen; Mengen, Festigkeit und Ausbeute sind noch in der Küche zu bestätigen.</p><p>Vorschlag für Ganache-Trüffel aus dunkler Schokolade, Sahne und Butter mit dünner Kakaoschicht, ohne Schokoladenhülle oder zugesetzten Alkohol. Ungefüllte Tafel zum Schmelzen mit 70 % Kakao wählen; USDA beschreibt den allgemeinen Bereich 70–85 %, keine Analyse der Marke oder des genauen Prozentsatzes. Pasteurisierte flüssige Schlagsahne mit 36 % Fett verwenden, keine saure Sahne oder pflanzliche Schlagcreme; USDA ist allgemein und Marken variieren. Enthält Milch; Etiketten von Schokolade, Kakao und Milchprodukten einschließlich Soja und Nussspuren oder weiterer Allergene prüfen. Keine Garantie für Glutenfreiheit, Allergieverträglichkeit oder vegane Eignung. Andere Schokolade, Kakaoanteile, Sahne oder Butter verändern Festigkeit und Nährwerte; anpassen und neu berechnen. Gesamter gewogener Kakao wird geschätzt einbezogen; bei Tellerresten haftende Menge vor Bestätigung messen, keine Aufnahme oder Verluste erfinden. Kein zusätzlicher Zucker, Vanille, Likör, Nüsse oder Beilagen. Trockene Geräte nutzen, heiße Sahne vorsichtig handhaben und Wasser aus Ganache fernhalten. Binnen 2 Stunden bei höchstens 4 °C kühlen, über 32 °C binnen 1 Stunde; gesamte Zeit draußen zählen, Sahne und lauwarme Ganache nicht warten lassen. Kein bei Raumtemperatur haltbares Produkt behauptet. Vorgeschlagene 24 Stunden sind ungeprüftes Qualitätskriterium, keine validierte Lagerung. Keine Küchenprüfung oder Gesundheitswirkung behauptet.</p>"}, {"id": "096884f7-ec8f-54c5-ac87-7b3842a96673", "recipe_group_id": "b5dc3c62-05ba-4ce6-8748-39570d2271a9", "slug": "chocolate-truffle-recipes", "public_path": "/en/chocolate-truffle-recipes", "source_url": "https://manualdecocina.com/en/chocolate-truffle-recipes/", "language": "en", "title": "Proposed dark chocolate truffles with cocoa", "excerpt": "Dark chocolate, cream and butter ganache with a thin cocoa coating: twenty proposed pieces and complete chilling times.", "summary": "Proposed ganache truffles made with dark chocolate, pasteurized cream, butter and natural cocoa. A proposed 20 individual pieces in 202 complete minutes including both chilling periods; quantities, firmness and yield await kitchen confirmation.", "category": "Desserts", "category_slug": "postres", "difficulty": "Medium", "course": "Dessert", "cuisine": "French-inspired", "prep_time_minutes": 30, "cook_time_minutes": 5, "total_time_minutes": 202, "servings": 20, "ingredients": [{"name": "plain dark chocolate bar for melting, 70 % cocoa, without filling", "amount": "200", "unit": "g", "group": "Ganache"}, {"name": "pasteurized liquid heavy whipping cream, 36 % fat", "amount": "100", "unit": "g", "group": "Ganache"}, {"name": "unsalted butter", "amount": "20", "unit": "g", "group": "Ganache"}, {"name": "natural unsweetened cocoa powder for coating", "amount": "10", "unit": "g", "group": "Coating"}], "steps": [{"title": "Prepare and weigh", "content": "Wash your hands and prepare scales, knife, heatproof bowl, small saucepan, spatula, shallow lidded container and tray lined with baking parchment. Weigh 200 g plain dark chocolate bar with 70 % cocoa, without filling or compound coating, and finely chop into the dry bowl. Weigh 100 g pasteurized liquid whipping cream with 36 % fat, 20 g unsalted butter and 10 g natural unsweetened cocoa. Cut butter into small cubes and soften for about 20 minutes; weigh and chop during the first 5 of that interval. Keep cream refrigerated until heating. Do not add sugar, vanilla, liqueur, nuts or extra chocolate.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-01.webp", "image_alt": "Proposed dark chocolate truffles with cocoa: Prepare and weigh"}, {"title": "Heat the cream without reducing it", "content": "Put the 100 g cream in the saucepan and heat over medium-low heat, stirring, for about 5 minutes until steam and small bubbles appear around the edge. Remove before a vigorous boil: the aim is heating, not reducing or boiling for several minutes. Carefully pour all hot cream over the chopped chocolate, avoiding burns. If heating takes longer, add actual time; watch the saucepan throughout heating.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-02.webp", "image_alt": "Proposed dark chocolate truffles with cocoa: Heat the cream without reducing it"}, {"title": "Emulsify with butter", "content": "Leave chocolate covered by cream for about 2 minutes without stirring. Then stir from the center with a spatula for about 3 minutes, incorporating the 20 g soft butter until ganache is uniform, without visible pieces or separated oil. Do not whip or add unweighed liquid. If pieces remain, gently warm the bowl over barely hot water without letting its base touch the water, stir gently and add extra time; keep water out. If not homogeneous, review chocolate type and temperature before continuing.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-03.webp", "image_alt": "Proposed dark chocolate truffles with cocoa: Emulsify with butter"}, {"title": "Chill the ganache covered", "content": "Transfer all ganache to a shallow container, cover and refrigerate at 4 °C or below for about 120 minutes until firm but scoopable. Chill this small quantity promptly rather than leaving it lukewarm outside. Perishables must be refrigerated within 2 hours, or 1 hour above 32 °C. If too soft, extend chilling and add actual time. Firmness depends on brand, fat and temperature and awaits kitchen confirmation.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-04.webp", "image_alt": "Proposed dark chocolate truffles with cocoa: Chill the ganache covered"}, {"title": "Shape and coat the truffles", "content": "Use clean dry hands and utensils. Weigh the actual chilled ganache and divide by 20 for similar portions; the initial 320 g ganache would suggest about 16 g per center, but is not a measured final yield. Shape slightly irregular balls without warming them too much with your hands. Use the reserved 10 g cocoa in a small dish for a thin coating, without additional melted chocolate. Allow about 20 minutes. If ganache is too hard, wait about 5 minutes before shaping and add them; if softening, chill again and record the time. The estimate includes all weighed cocoa; if some remains, weigh the retained amount before confirming nutrition and do not force its incorporation.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-05.webp", "image_alt": "Proposed dark chocolate truffles with cocoa: Shape and coat the truffles"}, {"title": "Firm up in the refrigerator", "content": "Place all truffles in one layer on baking parchment inside a clean container, cover and refrigerate at 4 °C or below for about 30 minutes until they hold their shape. Do not freeze to shorten the process or add more cocoa. Add actual extra chilling time if needed. Twenty pieces are proposed, not a tested yield; keep covered until serving.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-06.webp", "image_alt": "Proposed dark chocolate truffles with cocoa: Firm up in the refrigerator"}, {"title": "Serve and store", "content": "Allow about 2 minutes to serve only the pieces needed; a proposed 1 truffle per serving and twenty pieces. The 330 g is the initial sum, not measured final weight. The proposed total is 202 minutes: softening and preparation 20, heating 5, resting and mixing 5, first chill 120, shaping and coating 20, second chill 30 and serving 2. Quantities, timings and servings await kitchen confirmation. Store covered at 4 °C or below. Eating within 24 hours is an untested quality proposal, not validated shelf life; no freezing period is specified. Do not reuse plate leftovers or judge safety by smell; count all time outside refrigeration.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "image_alt": "Proposed dark chocolate truffles with cocoa: Serve and store"}], "nutrition": {"calories": 85.1, "protein_g": 1.0, "carbs_g": 5.0, "fat_g": 6.9, "saturated_fat_g": 4.1, "fiber_g": 1.3, "sugar_g": 2.6, "sodium_mg": 3.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "plain dark chocolate bar for melting, 70 % cocoa, without filling", "edible_grams": 200, "fdc_id": 170273, "fdc_description": "Chocolate, dark, 70-85% cacao solids", "per_100g": {"calories": 598, "protein_g": 7.79, "carbs_g": 45.9, "fat_g": 42.6, "saturated_fat_g": 24.5, "fiber_g": 10.9, "sugar_g": 24.0, "sodium_mg": 20.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170273/nutrients"}, {"ingredient": "pasteurized liquid heavy whipping cream, 36 % fat", "edible_grams": 100, "fdc_id": 170859, "fdc_description": "Cream, fluid, heavy whipping", "per_100g": {"calories": 340, "protein_g": 2.84, "carbs_g": 2.84, "fat_g": 36.1, "saturated_fat_g": 23.0, "fiber_g": 0.0, "sugar_g": 2.92, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170859/nutrients"}, {"ingredient": "unsalted butter", "edible_grams": 20, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "natural unsweetened cocoa powder for coating", "edible_grams": 10, "fdc_id": 169593, "fdc_description": "Cocoa, dry powder, unsweetened", "per_100g": {"calories": 228, "protein_g": 19.6, "carbs_g": 57.9, "fat_g": 13.7, "saturated_fat_g": 8.07, "fiber_g": 37.0, "sugar_g": 1.75, "sodium_mg": 21.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169593/nutrients"}], "serving_size": "One truffle; 20 proposed pieces", "method": "Sum grams multiplied by USDA values per 100 g, divided by 20. Four exact foods and eight nutrients reported for each; missing data are never invented.", "note": "Estimate awaiting confirmation, not analysis or kitchen testing. 330 g is initial weight, not measured final yield. Generic USDA dark chocolate with 70–85 % cocoa, not analysis of a particular 70 % bar. Generic whipping cream and butter; brand, fat and moisture vary. All 10 g coating cocoa are included; weigh adhered cocoa if some remains before confirming nutrition. No invented evaporation, utensil residue or cocoa absorption losses. Excludes chocolate shell, alcohol, extra sugar and accompaniments."}, "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "gallery": [{"url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "alt": "Twenty small slightly irregular dark chocolate truffles with a thin matte brown cocoa coating, without decorations or a chocolate shell"}], "published": false, "editorial_status": "draft", "keywords": ["chocolate truffles", "cocoa-coated ganache", "truffles without added alcohol"], "notes": "Proposed dark chocolate, cream and butter ganache truffles with a thin cocoa coating, without a chocolate shell or added alcohol. Choose a plain melting bar with 70 % cocoa; the USDA reference represents the generic 70–85 % interval, not analysis of that brand or exact percentage. Cream must be pasteurized liquid whipping cream with 36 % fat, not sour cream or vegetable topping; the USDA profile is generic and brands vary. Contains milk; check chocolate, cocoa and dairy labels, including soy and traces of nuts or other allergens. No gluten-free, allergy-safe or vegan suitability is guaranteed. Changing chocolate, cocoa percentage, cream or butter changes firmness and nutrition and requires adjustment and recalculation. All weighed cocoa is estimated as included; if some stays on the dish, measure the adhered amount before confirmation and do not invent absorption or losses. No extra sugar, vanilla, liqueur, nuts or accompaniments. Use dry utensils, handle hot cream carefully and keep water out of ganache. Refrigerate at 4 °C or below within 2 hours, or 1 hour above 32 °C; count accumulated time outside and do not leave cream or lukewarm ganache waiting. Not presented as shelf-stable at room temperature. The proposed 24 hours is an untested quality criterion, not validated storage. No kitchen trial or health benefit claimed.", "seo": {"title": "Dark chocolate truffles with cocoa, step by step", "description": "Chocolate, cream and butter ganache: quantities for twenty proposed truffles, two chilling periods, thin cocoa coating and storage.", "image_alt": "Twenty small slightly irregular dark chocolate truffles with a thin matte brown cocoa coating, without decorations or a chocolate shell", "image_variants": ["/recetas/recetas-de-trufas-de-chocolate/portada-1x1.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-4x3.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-16x9.webp"], "faq": [{"q": "Can I use milk chocolate, white chocolate or chips?", "a": "Not as a direct substitution. The proposal uses a plain dark chocolate bar with 70 % cocoa; changing chocolate requires reviewing the cream and butter ratio. Chips may contain ingredients affecting melting. The USDA calculation is generic for 70–85 %, not analysis of the chosen brand."}, {"q": "What if ganache is too soft or hard?", "a": "Chill soft ganache longer until scoopable and add actual time. If very hard, let it soften briefly before shaping while observing storage limits. Review brand, fat and emulsion; do not improvise unmeasured additions or claim this texture has been tested. Include additional pauses."}, {"q": "How long does it take and how is it stored?", "a": "A proposed 202 minutes includes preparation, heating, resting, both chills, shaping and serving. Add extra actual time. Store at 4 °C or below and refrigerate within 2 hours, or 1 hour above 32 °C. Eating within 24 hours is an untested quality proposal, not validated shelf life; room-temperature storage is not guaranteed."}]}, "content_html": "<p>Proposed ganache truffles made with dark chocolate, pasteurized cream, butter and natural cocoa. A proposed 20 individual pieces in 202 complete minutes including both chilling periods; quantities, firmness and yield await kitchen confirmation.</p><p>Proposed dark chocolate, cream and butter ganache truffles with a thin cocoa coating, without a chocolate shell or added alcohol. Choose a plain melting bar with 70 % cocoa; the USDA reference represents the generic 70–85 % interval, not analysis of that brand or exact percentage. Cream must be pasteurized liquid whipping cream with 36 % fat, not sour cream or vegetable topping; the USDA profile is generic and brands vary. Contains milk; check chocolate, cocoa and dairy labels, including soy and traces of nuts or other allergens. No gluten-free, allergy-safe or vegan suitability is guaranteed. Changing chocolate, cocoa percentage, cream or butter changes firmness and nutrition and requires adjustment and recalculation. All weighed cocoa is estimated as included; if some stays on the dish, measure the adhered amount before confirmation and do not invent absorption or losses. No extra sugar, vanilla, liqueur, nuts or accompaniments. Use dry utensils, handle hot cream carefully and keep water out of ganache. Refrigerate at 4 °C or below within 2 hours, or 1 hour above 32 °C; count accumulated time outside and do not leave cream or lukewarm ganache waiting. Not presented as shelf-stable at room temperature. The proposed 24 hours is an untested quality criterion, not validated storage. No kitchen trial or health benefit claimed.</p>"}, {"id": "39ab9501-cdf1-5ec4-94ae-9e416c406085", "recipe_group_id": "b5dc3c62-05ba-4ce6-8748-39570d2271a9", "slug": "recettes-de-truffe-au-chocolat", "public_path": "/fr/recettes-de-truffe-au-chocolat", "source_url": "https://manualdecocina.com/fr/recettes-de-truffe-au-chocolat/", "language": "fr", "title": "Proposition de truffes au chocolat noir et au cacao", "excerpt": "Ganache au chocolat noir, à la crème et au beurre, fine couche de cacao : vingt pièces proposées et durées complètes de réfrigération.", "summary": "Truffes de ganache proposées avec chocolat noir, crème pasteurisée, beurre et cacao naturel. On propose 20 pièces individuelles et 202 minutes au total, avec les deux périodes au froid ; quantités, fermeté et rendement restent à confirmer en cuisine.", "category": "Desserts", "category_slug": "postres", "difficulty": "Moyenne", "course": "Dessert", "cuisine": "Inspiration française", "prep_time_minutes": 30, "cook_time_minutes": 5, "total_time_minutes": 202, "servings": 20, "ingredients": [{"name": "tablette de chocolat noir à fondre, 70 % de cacao, sans garniture", "amount": "200", "unit": "g", "group": "Ganache"}, {"name": "crème liquide entière pasteurisée à fouetter, 36 % de matière grasse", "amount": "100", "unit": "g", "group": "Ganache"}, {"name": "beurre doux", "amount": "20", "unit": "g", "group": "Ganache"}, {"name": "cacao naturel pur en poudre non sucré pour l’enrobage", "amount": "10", "unit": "g", "group": "Enrobage"}], "steps": [{"title": "Préparer et peser", "content": "Lavez-vous les mains et préparez balance, couteau, bol résistant à la chaleur, petite casserole, spatule, récipient peu profond avec couvercle et plateau garni de papier cuisson. Pesez 200 g de chocolat noir en tablette à 70 % de cacao, sans garniture ni substitut d’enrobage, et hachez-le finement dans le bol sec. Pesez 100 g de crème liquide pasteurisée à fouetter à 36 % de matière grasse, 20 g de beurre doux et 10 g de cacao naturel pur non sucré. Coupez le beurre en petits dés et laissez ramollir environ 20 minutes ; pesez et hachez pendant les premières 5 minutes de cet intervalle. Gardez la crème au froid jusqu’au chauffage. N’ajoutez ni sucre, ni vanille, ni liqueur, ni fruits à coque, ni chocolat supplémentaire.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-01.webp", "image_alt": "Proposition de truffes au chocolat noir et au cacao: Préparer et peser"}, {"title": "Chauffer la crème sans la réduire", "content": "Mettez les 100 g de crème dans la casserole et chauffez à feu moyen-doux, en remuant, environ 5 minutes jusqu’à apparition de vapeur et de petites bulles au bord. Retirez avant une forte ébullition : on chauffe sans réduire ni faire bouillir plusieurs minutes. Versez toute la crème chaude sur le chocolat haché avec précaution pour éviter les brûlures. Si cela prend plus longtemps, ajoutez la durée réelle ; surveillez la casserole pendant tout le chauffage.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-02.webp", "image_alt": "Proposition de truffes au chocolat noir et au cacao: Chauffer la crème sans la réduire"}, {"title": "Émulsionner avec le beurre", "content": "Laissez le chocolat couvert par la crème environ 2 minutes sans remuer. Mélangez ensuite du centre vers l’extérieur à la spatule environ 3 minutes, en incorporant les 20 g de beurre mou, pour obtenir une ganache homogène sans morceaux visibles ni huile séparée. Ne fouettez pas pour monter et n’ajoutez pas de liquide non pesé. Si des morceaux restent, chauffez doucement le bol au-dessus d’eau à peine chaude sans que son fond touche l’eau, remuez et ajoutez la durée supplémentaire ; évitez toute entrée d’eau. Si le mélange n’est pas homogène, vérifiez type de chocolat et température avant de continuer.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-03.webp", "image_alt": "Proposition de truffes au chocolat noir et au cacao: Émulsionner avec le beurre"}, {"title": "Réfrigérer la ganache à couvert", "content": "Transférez toute la ganache dans un récipient peu profond, couvrez et réfrigérez à 4 °C ou moins environ 120 minutes jusqu’à consistance ferme mais prélevable à la cuillère. Refroidissez cette petite quantité immédiatement, sans la laisser attendre tiède dehors. Les aliments périssables doivent être réfrigérés dans les 2 heures, ou 1 heure au-dessus de 32 °C. Si elle reste trop molle, prolongez le froid et ajoutez la durée réelle. La fermeté dépend de la marque, du gras et de la température et reste à confirmer en cuisine.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-04.webp", "image_alt": "Proposition de truffes au chocolat noir et au cacao: Réfrigérer la ganache à couvert"}, {"title": "Former et enrober les truffes", "content": "Utilisez des mains et ustensiles propres et secs. Pesez la ganache froide réelle et divisez par 20 pour des portions similaires ; les 320 g initiaux suggéreraient environ 16 g par cœur, sans être un rendement final mesuré. Formez des boules légèrement irrégulières sans trop les chauffer avec les mains. Utilisez les 10 g de cacao réservés dans une petite assiette pour une fine couche, sans chocolat fondu supplémentaire. Prévoyez environ 20 minutes. Si la ganache est trop dure, attendez environ 5 minutes avant façonnage et ajoutez-les ; si elle ramollit, réfrigérez à nouveau et notez la durée. L’estimation inclut tout le cacao pesé ; s’il en reste, pesez la quantité retenue avant confirmation nutritionnelle, sans forcer son incorporation.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-05.webp", "image_alt": "Proposition de truffes au chocolat noir et au cacao: Former et enrober les truffes"}, {"title": "Raffermir au froid", "content": "Disposez toutes les truffes en une seule couche sur du papier cuisson dans un récipient propre, couvrez et réfrigérez à 4 °C ou moins environ 30 minutes jusqu’à tenue de leur forme. Ne congelez pas pour accélérer et n’ajoutez pas de cacao. Ajoutez la durée réelle si elles nécessitent plus de froid. Vingt pièces sont proposées, pas un rendement testé ; gardez le récipient couvert jusqu’au service.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-06.webp", "image_alt": "Proposition de truffes au chocolat noir et au cacao: Raffermir au froid"}, {"title": "Servir et conserver", "content": "Prévoyez environ 2 minutes pour servir seulement les pièces nécessaires ; on propose 1 truffe par portion et vingt pièces. Les 330 g sont la somme initiale, pas le poids final mesuré. Le total proposé est de 202 minutes : ramollissement et préparation 20, chauffage 5, repos et mélange 5, premier froid 120, façonnage et enrobage 20, second froid 30 et service 2. Quantités, durées et portions restent à confirmer en cuisine. Gardez à couvert à 4 °C ou moins. Consommer dans les 24 heures est une proposition de qualité non testée, pas une durée de conservation validée ; aucune durée de congélation définie. Ne réutilisez pas les restes d’assiette, ne jugez pas la sécurité à l’odeur et comptez tout le temps hors du réfrigérateur.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "image_alt": "Proposition de truffes au chocolat noir et au cacao: Servir et conserver"}], "nutrition": {"calories": 85.1, "protein_g": 1.0, "carbs_g": 5.0, "fat_g": 6.9, "saturated_fat_g": 4.1, "fiber_g": 1.3, "sugar_g": 2.6, "sodium_mg": 3.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "tablette de chocolat noir à fondre, 70 % de cacao, sans garniture", "edible_grams": 200, "fdc_id": 170273, "fdc_description": "Chocolate, dark, 70-85% cacao solids", "per_100g": {"calories": 598, "protein_g": 7.79, "carbs_g": 45.9, "fat_g": 42.6, "saturated_fat_g": 24.5, "fiber_g": 10.9, "sugar_g": 24.0, "sodium_mg": 20.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170273/nutrients"}, {"ingredient": "crème liquide entière pasteurisée à fouetter, 36 % de matière grasse", "edible_grams": 100, "fdc_id": 170859, "fdc_description": "Cream, fluid, heavy whipping", "per_100g": {"calories": 340, "protein_g": 2.84, "carbs_g": 2.84, "fat_g": 36.1, "saturated_fat_g": 23.0, "fiber_g": 0.0, "sugar_g": 2.92, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170859/nutrients"}, {"ingredient": "beurre doux", "edible_grams": 20, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "cacao naturel pur en poudre non sucré pour l’enrobage", "edible_grams": 10, "fdc_id": 169593, "fdc_description": "Cocoa, dry powder, unsweetened", "per_100g": {"calories": 228, "protein_g": 19.6, "carbs_g": 57.9, "fat_g": 13.7, "saturated_fat_g": 8.07, "fiber_g": 37.0, "sugar_g": 1.75, "sodium_mg": 21.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169593/nutrients"}], "serving_size": "Une truffe ; 20 pièces proposées", "method": "Somme des grammes multipliés par les valeurs USDA pour 100 g, divisée par 20. Quatre aliments exacts avec huit nutriments renseignés pour chacun ; aucune donnée manquante inventée.", "note": "Estimation à confirmer, pas analyse ni essai en cuisine. 330 g est le poids initial, pas un rendement final mesuré. Chocolat USDA générique à 70–85 % de cacao, pas analyse d’une tablette particulière à 70 %. Crème à fouetter et beurre génériques ; marques, gras et humidité varient. Tous les 10 g de cacao d’enrobage sont inclus ; pesez le cacao adhérent s’il en reste avant confirmation nutritionnelle. Aucune perte par évaporation, résidus sur les ustensiles ou absorption de cacao inventée. Exclut coque de chocolat, alcool, sucre supplémentaire et accompagnements."}, "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "gallery": [{"url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "alt": "Vingt petites truffes au chocolat noir légèrement irrégulières avec fine couche de cacao brun mat, sans décoration ni coque de chocolat"}], "published": false, "editorial_status": "draft", "keywords": ["truffes au chocolat", "ganache au cacao", "truffes sans alcool ajouté"], "notes": "Proposition de truffes de ganache au chocolat noir, crème et beurre, avec fine couche de cacao, sans coque de chocolat ni alcool ajouté. Choisissez une tablette nature à fondre à 70 % de cacao ; USDA représente l’intervalle générique 70–85 %, pas l’analyse de la marque ou du pourcentage exact. La crème doit être liquide, pasteurisée, à fouetter, à 36 % de matière grasse, pas crème aigre ni préparation végétale ; la fiche USDA est générique et les marques varient. Contient du lait ; vérifiez chocolat, cacao et produits laitiers, soja et traces de fruits à coque ou autres allergènes. Ni absence de gluten, ni compatibilité avec les allergies, ni version végétalienne garanties. Modifier chocolat, pourcentage de cacao, crème ou beurre change fermeté et nutrition : adaptez et recalculez. Tout le cacao pesé est estimé inclus ; s’il en reste sur l’assiette, mesurez la quantité adhérente avant confirmation, sans inventer absorption ou pertes. Aucun sucre, vanille, liqueur, fruits à coque ou accompagnement supplémentaires. Utilisez des ustensiles secs, manipulez la crème chaude avec soin et évitez l’eau dans la ganache. Réfrigérez à 4 °C ou moins dans les 2 heures, ou 1 heure au-dessus de 32 °C ; comptez le temps cumulé dehors et ne laissez pas crème ou ganache tiède attendre. Aucun caractère stable à température ambiante revendiqué. Les 24 heures proposées sont un critère de qualité non testé, pas une conservation validée. Aucun essai en cuisine ni bénéfice santé affirmé.", "seo": {"title": "Truffes au chocolat noir et au cacao, étape par étape", "description": "Ganache de chocolat, crème et beurre : quantités pour vingt truffes proposées, deux périodes au froid, fine couche de cacao et conservation.", "image_alt": "Vingt petites truffes au chocolat noir légèrement irrégulières avec fine couche de cacao brun mat, sans décoration ni coque de chocolat", "image_variants": ["/recetas/recetas-de-trufas-de-chocolate/portada-1x1.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-4x3.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-16x9.webp"], "faq": [{"q": "Puis-je utiliser chocolat au lait, blanc ou pépites ?", "a": "Pas en remplacement direct. La proposition utilise une tablette nature de chocolat noir à 70 % de cacao ; revoir le rapport avec crème et beurre si le chocolat change. Les pépites peuvent contenir des ingrédients influençant la fonte. USDA calcule un profil générique à 70–85 %, pas la marque choisie."}, {"q": "Que faire si la ganache est trop molle ou dure ?", "a": "Réfrigérez davantage une ganache molle jusqu’à pouvoir la portionner et ajoutez la durée réelle. Si elle est très dure, laissez brièvement ramollir avant façonnage en respectant les limites de conservation. Vérifiez marque, gras et émulsion ; n’improvisez pas d’ajouts non pesés et ne présentez pas cette texture comme testée. Comptez les pauses supplémentaires."}, {"q": "Quelle durée prévoir et comment conserver ?", "a": "On propose 202 minutes comprenant préparation, chauffage, repos, deux périodes au froid, façonnage et service. Ajoutez les durées réelles supplémentaires. Gardez à 4 °C ou moins et réfrigérez dans les 2 heures, ou 1 heure au-dessus de 32 °C. Consommer dans les 24 heures est une proposition de qualité non testée, pas une conservation validée ; le stockage à température ambiante n’est pas garanti."}]}, "content_html": "<p>Truffes de ganache proposées avec chocolat noir, crème pasteurisée, beurre et cacao naturel. On propose 20 pièces individuelles et 202 minutes au total, avec les deux périodes au froid ; quantités, fermeté et rendement restent à confirmer en cuisine.</p><p>Proposition de truffes de ganache au chocolat noir, crème et beurre, avec fine couche de cacao, sans coque de chocolat ni alcool ajouté. Choisissez une tablette nature à fondre à 70 % de cacao ; USDA représente l’intervalle générique 70–85 %, pas l’analyse de la marque ou du pourcentage exact. La crème doit être liquide, pasteurisée, à fouetter, à 36 % de matière grasse, pas crème aigre ni préparation végétale ; la fiche USDA est générique et les marques varient. Contient du lait ; vérifiez chocolat, cacao et produits laitiers, soja et traces de fruits à coque ou autres allergènes. Ni absence de gluten, ni compatibilité avec les allergies, ni version végétalienne garanties. Modifier chocolat, pourcentage de cacao, crème ou beurre change fermeté et nutrition : adaptez et recalculez. Tout le cacao pesé est estimé inclus ; s’il en reste sur l’assiette, mesurez la quantité adhérente avant confirmation, sans inventer absorption ou pertes. Aucun sucre, vanille, liqueur, fruits à coque ou accompagnement supplémentaires. Utilisez des ustensiles secs, manipulez la crème chaude avec soin et évitez l’eau dans la ganache. Réfrigérez à 4 °C ou moins dans les 2 heures, ou 1 heure au-dessus de 32 °C ; comptez le temps cumulé dehors et ne laissez pas crème ou ganache tiède attendre. Aucun caractère stable à température ambiante revendiqué. Les 24 heures proposées sont un critère de qualité non testé, pas une conservation validée. Aucun essai en cuisine ni bénéfice santé affirmé.</p>"}, {"id": "f8affcd8-7498-54e0-b3fc-491a6cfb01f1", "recipe_group_id": "b5dc3c62-05ba-4ce6-8748-39570d2271a9", "slug": "tartufi-al-cioccolato", "public_path": "/it/tartufi-al-cioccolato", "source_url": null, "language": "it", "title": "Proposta di tartufi al cioccolato fondente e cacao", "excerpt": "Ganache di fondente, panna e burro con un velo di cacao: venti pezzi proposti e tempi completi di raffreddamento.", "summary": "Tartufi di ganache proposti con cioccolato fondente, panna pastorizzata, burro e cacao naturale. Si propongono 20 pezzi singoli e 202 minuti complessivi, inclusi entrambi i periodi al freddo; quantità, consistenza e resa attendono conferma in cucina.", "category": "Dolci", "category_slug": "postres", "difficulty": "Media", "course": "Dessert", "cuisine": "Ispirazione francese", "prep_time_minutes": 30, "cook_time_minutes": 5, "total_time_minutes": 202, "servings": 20, "ingredients": [{"name": "tavoletta di cioccolato fondente da sciogliere, 70 % di cacao, senza ripieno", "amount": "200", "unit": "g", "group": "Ganache"}, {"name": "panna liquida pastorizzata da montare, 36 % di grassi", "amount": "100", "unit": "g", "group": "Ganache"}, {"name": "burro non salato", "amount": "20", "unit": "g", "group": "Ganache"}, {"name": "cacao naturale puro in polvere senza zucchero per rivestire", "amount": "10", "unit": "g", "group": "Rivestimento"}], "steps": [{"title": "Preparare e pesare", "content": "Lava le mani e prepara bilancia, coltello, ciotola resistente al calore, pentolino, spatola, contenitore poco profondo con coperchio e vassoio con carta forno. Pesa 200 g di fondente in tavoletta al 70 % di cacao, senza ripieno o surrogato di copertura, e tritalo finemente nella ciotola asciutta. Pesa 100 g di panna liquida pastorizzata da montare al 36 % di grassi, 20 g di burro non salato e 10 g di cacao naturale puro senza zucchero. Taglia il burro a dadini e lascialo ammorbidire circa 20 minuti; pesa e trita nei primi 5 di quell’intervallo. Mantieni la panna refrigerata fino al riscaldamento. Non aggiungere zucchero, vaniglia, liquore, frutta a guscio o altro cioccolato.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-01.webp", "image_alt": "Proposta di tartufi al cioccolato fondente e cacao: Preparare e pesare"}, {"title": "Scaldare la panna senza ridurla", "content": "Metti i 100 g di panna nel pentolino e scalda a fuoco medio-basso, mescolando, circa 5 minuti finché compaiono vapore e piccole bolle sul bordo. Togli prima di un bollore intenso: bisogna scaldare, non ridurre o bollire diversi minuti. Versa tutta la panna calda sul cioccolato tritato facendo attenzione alle scottature. Se occorre più tempo, aggiungi quello reale; sorveglia il pentolino per tutto il riscaldamento.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-02.webp", "image_alt": "Proposta di tartufi al cioccolato fondente e cacao: Scaldare la panna senza ridurla"}, {"title": "Emulsionare con il burro", "content": "Lascia il cioccolato coperto dalla panna circa 2 minuti senza toccarlo. Poi mescola dal centro con la spatola circa 3 minuti, incorporando i 20 g di burro morbido, fino a ganache uniforme senza pezzi visibili né olio separato. Non montare e non aggiungere liquidi non pesati. Se rimangono pezzi, scalda delicatamente la ciotola sopra acqua appena calda senza che il fondo tocchi l’acqua, mescola e aggiungi il tempo supplementare; evita che entri acqua. Se non è omogenea, verifica tipo di cioccolato e temperatura prima di continuare.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-03.webp", "image_alt": "Proposta di tartufi al cioccolato fondente e cacao: Emulsionare con il burro"}, {"title": "Raffreddare la ganache coperta", "content": "Trasferisci tutta la ganache in un contenitore poco profondo, copri e refrigera a 4 °C o meno circa 120 minuti, finché è soda ma prelevabile con un cucchiaio. Raffredda subito questa piccola quantità, senza lasciarla tiepida in attesa fuori. Gli alimenti deperibili devono essere refrigerati entro 2 ore, o 1 ora sopra 32 °C. Se troppo morbida, prolunga il freddo e aggiungi il tempo reale. La consistenza dipende da marca, grassi e temperatura e attende conferma in cucina.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-04.webp", "image_alt": "Proposta di tartufi al cioccolato fondente e cacao: Raffreddare la ganache coperta"}, {"title": "Formare e rivestire i tartufi", "content": "Usa mani e utensili puliti e asciutti. Pesa la ganache fredda reale e dividi per 20 per porzioni simili; i 320 g iniziali di ganache suggerirebbero circa 16 g per centro, ma non sono una resa finale misurata. Forma palline leggermente irregolari senza scaldarle troppo con le mani. Usa i 10 g di cacao riservati in un piattino per uno strato sottile, senza altro cioccolato fuso. Prevedi circa 20 minuti. Se la ganache è troppo dura, aspetta circa 5 minuti prima di formare e aggiungili; se si ammorbidisce, raffredda di nuovo e registra il tempo. La stima include tutto il cacao pesato; se avanza, pesa quello trattenuto prima di confermare la nutrizione e non forzarne l’incorporazione.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-05.webp", "image_alt": "Proposta di tartufi al cioccolato fondente e cacao: Formare e rivestire i tartufi"}, {"title": "Rassodare al freddo", "content": "Disponi tutti i tartufi in un solo strato su carta forno dentro un contenitore pulito, copri e refrigera a 4 °C o meno circa 30 minuti, finché mantengono la forma. Non congelare per accelerare e non aggiungere cacao. Se serve più freddo, aggiungi il tempo reale. Venti pezzi sono proposti, non una resa provata; conserva coperto fino al servizio.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-06.webp", "image_alt": "Proposta di tartufi al cioccolato fondente e cacao: Rassodare al freddo"}, {"title": "Servire e conservare", "content": "Prevedi circa 2 minuti per servire solo i pezzi necessari; si propone 1 tartufo per porzione e venti pezzi. I 330 g sono la somma iniziale, non un peso finale misurato. Il totale proposto è 202 minuti: ammorbidire e preparare 20, scaldare 5, riposare e mescolare 5, primo freddo 120, formare e rivestire 20, secondo freddo 30 e servire 2. Quantità, tempi e porzioni attendono conferma in cucina. Conserva coperto a 4 °C o meno. Consumare entro 24 ore è una proposta di qualità non provata, non durata validata; nessun tempo di congelamento stabilito. Non riutilizzare avanzi del piatto né valutare la sicurezza dall’odore; conta tutto il tempo fuori dal frigorifero.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "image_alt": "Proposta di tartufi al cioccolato fondente e cacao: Servire e conservare"}], "nutrition": {"calories": 85.1, "protein_g": 1.0, "carbs_g": 5.0, "fat_g": 6.9, "saturated_fat_g": 4.1, "fiber_g": 1.3, "sugar_g": 2.6, "sodium_mg": 3.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "tavoletta di cioccolato fondente da sciogliere, 70 % di cacao, senza ripieno", "edible_grams": 200, "fdc_id": 170273, "fdc_description": "Chocolate, dark, 70-85% cacao solids", "per_100g": {"calories": 598, "protein_g": 7.79, "carbs_g": 45.9, "fat_g": 42.6, "saturated_fat_g": 24.5, "fiber_g": 10.9, "sugar_g": 24.0, "sodium_mg": 20.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170273/nutrients"}, {"ingredient": "panna liquida pastorizzata da montare, 36 % di grassi", "edible_grams": 100, "fdc_id": 170859, "fdc_description": "Cream, fluid, heavy whipping", "per_100g": {"calories": 340, "protein_g": 2.84, "carbs_g": 2.84, "fat_g": 36.1, "saturated_fat_g": 23.0, "fiber_g": 0.0, "sugar_g": 2.92, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170859/nutrients"}, {"ingredient": "burro non salato", "edible_grams": 20, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "cacao naturale puro in polvere senza zucchero per rivestire", "edible_grams": 10, "fdc_id": 169593, "fdc_description": "Cocoa, dry powder, unsweetened", "per_100g": {"calories": 228, "protein_g": 19.6, "carbs_g": 57.9, "fat_g": 13.7, "saturated_fat_g": 8.07, "fiber_g": 37.0, "sugar_g": 1.75, "sodium_mg": 21.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169593/nutrients"}], "serving_size": "Un tartufo; 20 pezzi proposti", "method": "Somma dei grammi moltiplicati per valori USDA per 100 g, divisa per 20. Quattro alimenti esatti e otto nutrienti riportati per tutti; dati mancanti mai inventati.", "note": "Stima da confermare, non analisi né prova in cucina. 330 g è peso iniziale, non resa finale misurata. Fondente USDA generico al 70–85 % di cacao, non analisi di una tavoletta specifica al 70 %. Panna da montare e burro generici; marca, grassi e acqua variano. Include tutti i 10 g di cacao per rivestire; se avanza, pesa quello aderito prima di confermare nutrizione. Nessuna perdita per evaporazione, residui sugli utensili o assorbimento di cacao inventata. Esclude guscio di cioccolato, alcol, zucchero extra e accompagnamenti."}, "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "gallery": [{"url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "alt": "Venti piccoli tartufi al fondente leggermente irregolari con un velo di cacao marrone opaco, senza decorazioni o guscio di cioccolato"}], "published": false, "editorial_status": "draft", "keywords": ["tartufi al cioccolato", "ganache con cacao", "tartufi senza alcol aggiunto"], "notes": "Proposta di tartufi di ganache con fondente, panna, burro e sottile rivestimento di cacao, senza guscio di cioccolato o alcol aggiunto. Scegli tavoletta semplice da sciogliere al 70 % di cacao; USDA rappresenta l’intervallo generico 70–85 %, non l’analisi della marca o della percentuale esatta. Panna liquida pastorizzata da montare al 36 % di grassi, non panna acida né copertura vegetale; dati USDA generici e marche variabili. Contiene latte; verifica etichette di cioccolato, cacao e latticini, inclusi soia e tracce di frutta a guscio o altri allergeni. Non si garantiscono assenza di glutine, idoneità per allergie o versione vegana. Cambiare cioccolato, percentuale di cacao, panna o burro modifica consistenza e nutrizione; adatta e ricalcola. La stima include tutto il cacao pesato; se resta nel piatto, misura quello aderito prima della conferma, senza inventare assorbimento o perdite. Niente zucchero, vaniglia, liquore, frutta a guscio o accompagnamenti extra. Usa utensili asciutti, maneggia con cautela panna calda ed evita acqua nella ganache. Refrigerare a 4 °C o meno entro 2 ore, o 1 ora sopra 32 °C; conta il tempo cumulato fuori e non lasciare panna o ganache tiepida in attesa. Non presentato come prodotto stabile a temperatura ambiente. Le 24 ore proposte sono criterio di qualità non provato, non conservazione validata. Nessuna prova in cucina o beneficio per la salute affermati.", "seo": {"title": "Tartufi al cioccolato fondente e cacao passo dopo passo", "description": "Ganache di cioccolato, panna e burro: quantità per venti tartufi proposti, due periodi al freddo, velo di cacao e conservazione.", "image_alt": "Venti piccoli tartufi al fondente leggermente irregolari con un velo di cacao marrone opaco, senza decorazioni o guscio di cioccolato", "image_variants": ["/recetas/recetas-de-trufas-de-chocolate/portada-1x1.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-4x3.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-16x9.webp"], "faq": [{"q": "Posso usare cioccolato al latte, bianco o gocce?", "a": "Non come sostituzione diretta. La proposta usa tavoletta semplice di fondente al 70 % di cacao; cambiando cioccolato rivedi il rapporto con panna e burro. Le gocce possono contenere ingredienti che alterano la fusione. Il calcolo USDA è generico al 70–85 %, non analisi della marca scelta."}, {"q": "Cosa fare se la ganache è troppo morbida o dura?", "a": "Raffredda più a lungo quella morbida fino a poterla porzionare e aggiungi il tempo reale. Se molto dura, lasciala ammorbidire brevemente prima di formare rispettando i limiti di conservazione. Verifica marca, grassi ed emulsione; non improvvisare aggiunte non pesate o affermare che la consistenza è provata. Conta le pause aggiuntive."}, {"q": "Quanto tempo serve e come si conserva?", "a": "Si propongono 202 minuti con preparazione, riscaldamento, riposo, due periodi al freddo, formatura e servizio. Aggiungi i tempi reali supplementari. Mantieni a 4 °C o meno e refrigerare entro 2 ore, o 1 ora sopra 32 °C. Consumare entro 24 ore è proposta di qualità non provata, non durata validata; conservazione a temperatura ambiente non garantita."}]}, "content_html": "<p>Tartufi di ganache proposti con cioccolato fondente, panna pastorizzata, burro e cacao naturale. Si propongono 20 pezzi singoli e 202 minuti complessivi, inclusi entrambi i periodi al freddo; quantità, consistenza e resa attendono conferma in cucina.</p><p>Proposta di tartufi di ganache con fondente, panna, burro e sottile rivestimento di cacao, senza guscio di cioccolato o alcol aggiunto. Scegli tavoletta semplice da sciogliere al 70 % di cacao; USDA rappresenta l’intervallo generico 70–85 %, non l’analisi della marca o della percentuale esatta. Panna liquida pastorizzata da montare al 36 % di grassi, non panna acida né copertura vegetale; dati USDA generici e marche variabili. Contiene latte; verifica etichette di cioccolato, cacao e latticini, inclusi soia e tracce di frutta a guscio o altri allergeni. Non si garantiscono assenza di glutine, idoneità per allergie o versione vegana. Cambiare cioccolato, percentuale di cacao, panna o burro modifica consistenza e nutrizione; adatta e ricalcola. La stima include tutto il cacao pesato; se resta nel piatto, misura quello aderito prima della conferma, senza inventare assorbimento o perdite. Niente zucchero, vaniglia, liquore, frutta a guscio o accompagnamenti extra. Usa utensili asciutti, maneggia con cautela panna calda ed evita acqua nella ganache. Refrigerare a 4 °C o meno entro 2 ore, o 1 ora sopra 32 °C; conta il tempo cumulato fuori e non lasciare panna o ganache tiepida in attesa. Non presentato come prodotto stabile a temperatura ambiente. Le 24 ore proposte sono criterio di qualità non provato, non conservazione validata. Nessuna prova in cucina o beneficio per la salute affermati.</p>"}, {"id": "fb6c3831-5cd8-5b22-bf67-ffd229a5dd09", "recipe_group_id": "b5dc3c62-05ba-4ce6-8748-39570d2271a9", "slug": "チョコレートトリュフ", "public_path": "/ja/チョコレートトリュフ", "source_url": null, "language": "ja", "title": "ココアをまぶすダークチョコレートトリュフ案", "excerpt": "ダークチョコレート、生クリーム、バターのガナッシュに薄くココアをまぶす、二十個の提案。冷却時間も含みます。", "summary": "ダークチョコレート、殺菌済み生クリーム、バター、天然ココアのガナッシュトリュフ案です。20個、二回の冷却を含む合計202分を提案します。分量、固さ、出来上がり量は調理での確認待ちです。", "category": "デザート", "category_slug": "postres", "difficulty": "中程度", "course": "デザート", "cuisine": "フランス風", "prep_time_minutes": 30, "cook_time_minutes": 5, "total_time_minutes": 202, "servings": 20, "ingredients": [{"name": "溶かすためのダークチョコレート板、カカオ70 %、フィリングなし", "amount": "200", "unit": "g", "group": "ガナッシュ"}, {"name": "殺菌済み液状ホイップ用生クリーム、乳脂肪36 %", "amount": "100", "unit": "g", "group": "ガナッシュ"}, {"name": "食塩不使用バター", "amount": "20", "unit": "g", "group": "ガナッシュ"}, {"name": "まぶすための天然純ココア粉末、無糖", "amount": "10", "unit": "g", "group": "まぶす材料"}], "steps": [{"title": "準備して計量する", "content": "手を洗い、はかり、包丁、耐熱ボウル、小鍋、へら、浅いふた付き容器、オーブンペーパーを敷いたトレーを用意します。カカオ70 %のダークチョコレート板200 gを量り、乾いたボウルに細かく刻みます。フィリングや代用コーティングは使いません。乳脂肪36 %の殺菌済み液状ホイップ用生クリーム100 g、食塩不使用バター20 g、天然無糖ココア10 gを量ります。バターを小さく切り、約20分軟らかくします。その最初の5分で計量と刻む作業を行います。クリームは温める直前まで冷蔵します。砂糖、バニラ、リキュール、ナッツ、追加のチョコレートは入れません。", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-01.webp", "image_alt": "ココアをまぶすダークチョコレートトリュフ案: 準備して計量する"}, {"title": "クリームを煮詰めず温める", "content": "クリーム100 gを小鍋に入れ、中弱火で混ぜながら約5分、湯気と縁の小さな泡が出るまで温めます。激しく沸く前に火から下ろします。温めるのが目的で、煮詰めたり数分間沸騰させたりしません。やけどに注意して熱いクリーム全量を刻んだチョコレートに注ぎます。長くかかれば実際の時間を加え、加熱中は鍋を見守ります。", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-02.webp", "image_alt": "ココアをまぶすダークチョコレートトリュフ案: クリームを煮詰めず温める"}, {"title": "バターと乳化させる", "content": "チョコレートをクリームで覆ったまま約2分、触らず置きます。その後、へらで中央から約3分混ぜ、軟らかいバター20 gを加え、塊や油の分離がない均一なガナッシュにします。泡立てず、量っていない液体を加えません。塊が残る場合は、ボウルの底が湯に触れないよう穏やかに温かい湯の上で温め、優しく混ぜ、追加時間を加えます。水が入らないようにします。均一にならなければ、次に進む前にチョコレートの種類と温度を確認します。", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-03.webp", "image_alt": "ココアをまぶすダークチョコレートトリュフ案: バターと乳化させる"}, {"title": "ガナッシュにふたをして冷やす", "content": "ガナッシュ全量を浅い容器へ移し、ふたをして4 °C以下で約120分、固いがスプーンですくえる状態まで冷蔵します。この少量はすぐ冷やし、ぬるいまま外で待たせません。傷みやすい食品は2時間以内、32 °Cを超える場合は1時間以内に冷蔵します。軟らかすぎれば冷却を延長し、実際の時間を加えます。固さは銘柄、脂肪、温度に左右され、調理での確認待ちです。", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-04.webp", "image_alt": "ココアをまぶすダークチョコレートトリュフ案: ガナッシュにふたをして冷やす"}, {"title": "形を作りココアをまぶす", "content": "清潔で乾いた手と器具を使います。実際の冷たいガナッシュを量り、20で割って同程度に分けます。最初のガナッシュ320 gなら中心部は約16 gになりますが、完成品の実測量ではありません。手で温めすぎず、やや不規則な球にします。取っておいたココア10 gを小皿で薄くまぶし、溶かした追加のチョコレートは使いません。約20分を見込みます。ガナッシュが固すぎれば形を作る前に約5分待ち、その時間を加えます。軟らかくなれば再冷却して時間を記録します。推定には量ったココア全量を含みます。残る場合は栄養値を確定する前に付着量を量り、無理に全部を取り込ませません。", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-05.webp", "image_alt": "ココアをまぶすダークチョコレートトリュフ案: 形を作りココアをまぶす"}, {"title": "冷蔵して形を安定させる", "content": "清潔な容器のオーブンペーパー上に全トリュフを重ねず並べ、ふたをして4 °C以下で約30分、形が保てるまで冷蔵します。時間短縮のため冷凍したり、ココアを追加したりしません。冷却が延びる場合は実際の時間を加えます。二十個は提案であり、試作で確認した出来上がり量ではありません。提供までふたをしておきます。", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-06.webp", "image_alt": "ココアをまぶすダークチョコレートトリュフ案: 冷蔵して形を安定させる"}, {"title": "提供して保存する", "content": "必要な個数だけ約2分で提供します。一食分は1個、全体は二十個の提案です。330 gは最初の合計で、完成品の実測重量ではありません。合計202分の提案は、軟化と準備20、加熱5、休ませて混ぜる作業5、最初の冷却120、成形とまぶす作業20、次の冷却30、提供2です。分量、時間、人数は調理での確認待ちです。ふたをして4 °C以下で保存します。24時間以内に食べる目安は未検証の品質上の提案で、検証済み保存期限ではなく、冷凍期間も設定しません。皿の食べ残しを戻さず、においだけで安全性を判断せず、冷蔵庫の外に出した全時間を数えます。", "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "image_alt": "ココアをまぶすダークチョコレートトリュフ案: 提供して保存する"}], "nutrition": {"calories": 85.1, "protein_g": 1.0, "carbs_g": 5.0, "fat_g": 6.9, "saturated_fat_g": 4.1, "fiber_g": 1.3, "sugar_g": 2.6, "sodium_mg": 3.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "溶かすためのダークチョコレート板、カカオ70 %、フィリングなし", "edible_grams": 200, "fdc_id": 170273, "fdc_description": "Chocolate, dark, 70-85% cacao solids", "per_100g": {"calories": 598, "protein_g": 7.79, "carbs_g": 45.9, "fat_g": 42.6, "saturated_fat_g": 24.5, "fiber_g": 10.9, "sugar_g": 24.0, "sodium_mg": 20.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170273/nutrients"}, {"ingredient": "殺菌済み液状ホイップ用生クリーム、乳脂肪36 %", "edible_grams": 100, "fdc_id": 170859, "fdc_description": "Cream, fluid, heavy whipping", "per_100g": {"calories": 340, "protein_g": 2.84, "carbs_g": 2.84, "fat_g": 36.1, "saturated_fat_g": 23.0, "fiber_g": 0.0, "sugar_g": 2.92, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170859/nutrients"}, {"ingredient": "食塩不使用バター", "edible_grams": 20, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "まぶすための天然純ココア粉末、無糖", "edible_grams": 10, "fdc_id": 169593, "fdc_description": "Cocoa, dry powder, unsweetened", "per_100g": {"calories": 228, "protein_g": 19.6, "carbs_g": 57.9, "fat_g": 13.7, "saturated_fat_g": 8.07, "fiber_g": 37.0, "sugar_g": 1.75, "sodium_mg": 21.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169593/nutrients"}], "serving_size": "トリュフ一個；提案は20個", "method": "各材料の重量にUSDAの100 g当たり値を掛けて合計し、20で割ります。確認した四食品すべてで八栄養素が報告され、欠けたデータを作りません。", "note": "確認待ちの推定で、分析や調理試験ではありません。330 gは最初の重量で、完成重量の実測ではありません。USDAの一般的なカカオ70–85 %ダークチョコレートで、特定の70 %板の分析ではありません。生クリームとバターも一般値で、銘柄、脂肪、水分により変わります。まぶすココア10 g全量を含み、残る場合は栄養確認前に付着量を測ります。蒸発、器具への残り、ココア吸収の損失を架空に設定しません。チョコレートの殻、酒類、追加の砂糖、付け合わせは含みません。"}, "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "gallery": [{"url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "alt": "薄い茶色のマットなココアをまぶした、やや不規則な小さいダークチョコレートトリュフ二十個。飾りやチョコレートの殻なし"}], "published": false, "editorial_status": "draft", "keywords": ["チョコレートトリュフ", "ココアのガナッシュ", "酒類を加えないトリュフ"], "notes": "ダークチョコレート、生クリーム、バターのガナッシュに薄くココアをまぶす提案で、チョコレートの殻や追加の酒類は使いません。フィリングなしの溶かせるカカオ70 %板を選びます。USDAは一般的な70–85 %の範囲を示し、その銘柄や正確な割合の分析ではありません。生クリームは殺菌済み液状のホイップ用乳脂肪36 %で、サワークリームや植物性トッピングではありません。USDAは一般値で銘柄により変わります。乳を含むため、チョコレート、ココア、乳製品の表示と大豆、ナッツなどの交差接触を確認してください。グルテン不使用、アレルギーへの適合、ビーガン対応を保証しません。チョコレート、カカオ率、クリーム、バターの変更は固さと栄養に影響し、配合調整と再計算が必要です。量ったココア全量を含む推定ですが、皿に残る場合は確定前に付着量を測り、吸収や損失を作りません。追加の砂糖、バニラ、酒類、ナッツ、付け合わせは含みません。乾いた器具を使い、熱いクリームによるやけどとガナッシュへの水の混入を避けます。4 °C以下で2時間以内、32 °Cを超える場合は1時間以内に冷蔵し、外に出した累積時間を数えます。クリームやぬるいガナッシュを外で待たせず、常温保存できる製品とは説明しません。提案する24時間は未検証の品質目安で、保存期限の検証ではありません。調理試験や健康効果は主張しません。", "seo": {"title": "ダークチョコレートトリュフ：ココアと冷却の手順", "description": "チョコレート、生クリーム、バターのガナッシュ。二十個の提案、二回の冷却、薄いココアのまぶし方、保存手順を説明します。", "image_alt": "薄い茶色のマットなココアをまぶした、やや不規則な小さいダークチョコレートトリュフ二十個。飾りやチョコレートの殻なし", "image_variants": ["/recetas/recetas-de-trufas-de-chocolate/portada-1x1.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-4x3.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-16x9.webp"], "faq": [{"q": "ミルク、ホワイトチョコレートやチップに替えられますか？", "a": "そのままの置き換えはできません。提案はフィリングなしのカカオ70 %ダークチョコレート板で、変更時はクリームとバターの比率を見直します。チップには溶け方に影響する材料が含まれる場合があります。USDAの計算は一般的な70–85 %で、選んだ銘柄の分析ではありません。"}, {"q": "ガナッシュが軟らかすぎる、固すぎる場合は？", "a": "軟らかい場合はすくえるまで追加冷却し、実際の時間を加えます。固い場合は保存の限度を守り、成形前に短く軟らかくします。銘柄、脂肪、乳化を確認し、量っていない材料を思いつきで加えず、この固さを試作済みとは説明しません。追加の待ち時間も含めます。"}, {"q": "所要時間と保存方法は？", "a": "準備、加熱、休ませる時間、二回の冷却、成形、提供を含む202分を提案します。追加時間は加算します。4 °C以下で保ち、2時間以内、32 °Cを超える場合は1時間以内に冷蔵します。24時間以内の目安は未検証の品質提案で、保存期限の検証ではなく、常温保存を保証しません。"}]}, "content_html": "<p>ダークチョコレート、殺菌済み生クリーム、バター、天然ココアのガナッシュトリュフ案です。20個、二回の冷却を含む合計202分を提案します。分量、固さ、出来上がり量は調理での確認待ちです。</p><p>ダークチョコレート、生クリーム、バターのガナッシュに薄くココアをまぶす提案で、チョコレートの殻や追加の酒類は使いません。フィリングなしの溶かせるカカオ70 %板を選びます。USDAは一般的な70–85 %の範囲を示し、その銘柄や正確な割合の分析ではありません。生クリームは殺菌済み液状のホイップ用乳脂肪36 %で、サワークリームや植物性トッピングではありません。USDAは一般値で銘柄により変わります。乳を含むため、チョコレート、ココア、乳製品の表示と大豆、ナッツなどの交差接触を確認してください。グルテン不使用、アレルギーへの適合、ビーガン対応を保証しません。チョコレート、カカオ率、クリーム、バターの変更は固さと栄養に影響し、配合調整と再計算が必要です。量ったココア全量を含む推定ですが、皿に残る場合は確定前に付着量を測り、吸収や損失を作りません。追加の砂糖、バニラ、酒類、ナッツ、付け合わせは含みません。乾いた器具を使い、熱いクリームによるやけどとガナッシュへの水の混入を避けます。4 °C以下で2時間以内、32 °Cを超える場合は1時間以内に冷蔵し、外に出した累積時間を数えます。クリームやぬるいガナッシュを外で待たせず、常温保存できる製品とは説明しません。提案する24時間は未検証の品質目安で、保存期限の検証ではありません。調理試験や健康効果は主張しません。</p>"}, {"id": "9bb68837-f548-5a62-aabf-c3d23208a043", "recipe_group_id": "b5dc3c62-05ba-4ce6-8748-39570d2271a9", "slug": "trufas-de-chocolate", "public_path": "/pt/trufas-de-chocolate", "source_url": null, "language": "pt", "title": "Proposta de trufas de chocolate amargo com cacau", "excerpt": "Ganache de chocolate amargo, creme de leite e manteiga com uma fina camada de cacau: vinte unidades propostas e tempos completos de refrigeração.", "summary": "Trufas de ganache propostas com chocolate amargo, creme de leite pasteurizado, manteiga e cacau natural. São propostas 20 unidades individuais e 202 minutos completos, incluindo os dois períodos de refrigeração; quantidades, firmeza e rendimento aguardam confirmação na cozinha.", "category": "Sobremesas", "category_slug": "postres", "difficulty": "Média", "course": "Sobremesa", "cuisine": "Inspiração francesa", "prep_time_minutes": 30, "cook_time_minutes": 5, "total_time_minutes": 202, "servings": 20, "ingredients": [{"name": "chocolate amargo em barra para derreter, 70 % de cacau, sem recheio", "amount": "200", "unit": "g", "group": "Ganache"}, {"name": "creme de leite líquido pasteurizado para bater, 36 % de gordura", "amount": "100", "unit": "g", "group": "Ganache"}, {"name": "manteiga sem sal", "amount": "20", "unit": "g", "group": "Ganache"}, {"name": "cacau natural puro em pó sem açúcar, para cobertura", "amount": "10", "unit": "g", "group": "Cobertura"}], "steps": [{"title": "Prepare e pese", "content": "Lave as mãos e prepare balança, faca, tigela resistente ao calor, panela pequena, espátula, recipiente raso com tampa e bandeja com papel-manteiga. Pese 200 g de chocolate amargo em barra com 70 % de cacau, sem recheio nem substituto de cobertura, e pique bem na tigela seca. Pese 100 g de creme de leite líquido pasteurizado para bater com 36 % de gordura, 20 g de manteiga sem sal e 10 g de cacau natural puro sem açúcar. Corte a manteiga em cubinhos e deixe amolecer cerca de 20 minutos; pese e pique durante os primeiros 5 desse intervalo. Mantenha o creme refrigerado até aquecer. Não acrescente açúcar, baunilha, licor, castanhas nem mais chocolate.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-01.webp", "image_alt": "Proposta de trufas de chocolate amargo com cacau: Prepare e pese"}, {"title": "Aqueça o creme sem reduzir", "content": "Coloque os 100 g de creme na panela e aqueça em fogo médio-baixo, mexendo, por cerca de 5 minutos até surgir vapor e pequenas bolhas na borda. Retire antes de ferver intensamente: o objetivo é aquecer, não reduzir nem ferver por vários minutos. Despeje todo o creme quente sobre o chocolate picado, com cuidado para evitar queimaduras. Se demorar mais, some o tempo real; observe a panela durante todo o aquecimento.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-02.webp", "image_alt": "Proposta de trufas de chocolate amargo com cacau: Aqueça o creme sem reduzir"}, {"title": "Emulsione com a manteiga", "content": "Deixe o chocolate coberto pelo creme cerca de 2 minutos sem mexer. Depois misture a partir do centro com espátula por cerca de 3 minutos, incorporando os 20 g de manteiga macia, até uma ganache uniforme, sem pedaços visíveis nem óleo separado. Não bata para montar e não adicione líquido não pesado. Se restarem pedaços, aqueça suavemente a tigela sobre água apenas quente sem que o fundo toque na água, mexa e some o tempo adicional; evite entrada de água. Se não ficar homogênea, confira tipo de chocolate e temperatura antes de continuar.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-03.webp", "image_alt": "Proposta de trufas de chocolate amargo com cacau: Emulsione com a manteiga"}, {"title": "Refrigere a ganache tampada", "content": "Transfira toda a ganache para um recipiente raso, tampe e refrigere a 4 °C ou menos por cerca de 120 minutos, até ficar firme, mas possível de retirar com colher. Resfrie imediatamente essa pequena quantidade; não deixe morna esperando fora. Perecíveis devem ser refrigerados dentro de 2 horas, ou 1 hora acima de 32 °C. Se estiver muito mole, prolongue a refrigeração e some o tempo real. A firmeza depende da marca, gordura e temperatura e aguarda confirmação na cozinha.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-04.webp", "image_alt": "Proposta de trufas de chocolate amargo com cacau: Refrigere a ganache tampada"}, {"title": "Modele e cubra as trufas", "content": "Use mãos e utensílios limpos e secos. Pese a ganache fria real e divida por 20 para obter porções semelhantes; os 320 g iniciais sugeririam cerca de 16 g por centro, mas não são rendimento final medido. Forme bolas ligeiramente irregulares sem aquecê-las demais com as mãos. Use os 10 g de cacau reservados em um prato pequeno para uma camada fina, sem chocolate derretido adicional. Reserve cerca de 20 minutos. Se a ganache estiver dura demais, espere cerca de 5 minutos antes de modelar e some esse tempo; se amolecer, refrigere novamente e registre o tempo. A estimativa inclui todo o cacau pesado; se sobrar, pese o retido antes de confirmar nutrição e não force sua incorporação.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-05.webp", "image_alt": "Proposta de trufas de chocolate amargo com cacau: Modele e cubra as trufas"}, {"title": "Firme novamente na geladeira", "content": "Coloque todas as trufas em uma única camada sobre papel-manteiga em um recipiente limpo, tampe e refrigere a 4 °C ou menos por cerca de 30 minutos, até manterem a forma. Não congele para abreviar nem acrescente cacau. Se precisarem de mais refrigeração, some o tempo real. São propostas vinte unidades, não rendimento testado; mantenha tampado até servir.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/paso-06.webp", "image_alt": "Proposta de trufas de chocolate amargo com cacau: Firme novamente na geladeira"}, {"title": "Sirva e conserve", "content": "Reserve cerca de 2 minutos para servir apenas as unidades necessárias; propõe-se 1 trufa por porção e vinte unidades. Os 330 g são a soma inicial, não peso final medido. O total proposto é 202 minutos: amolecer e preparar 20, aquecer 5, repousar e misturar 5, primeiro frio 120, modelar e cobrir 20, segundo frio 30 e servir 2. Quantidades, tempos e porções aguardam confirmação na cozinha. Guarde tampadas a 4 °C ou menos. Consumir em 24 horas é uma proposta de qualidade não testada, não validade comprovada; não se define prazo de congelamento. Não reaproveite sobras do prato nem julgue segurança pelo cheiro; conte todo o tempo fora da geladeira.", "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "image_alt": "Proposta de trufas de chocolate amargo com cacau: Sirva e conserve"}], "nutrition": {"calories": 85.1, "protein_g": 1.0, "carbs_g": 5.0, "fat_g": 6.9, "saturated_fat_g": 4.1, "fiber_g": 1.3, "sugar_g": 2.6, "sodium_mg": 3.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy", "source_url": "https://fdc.nal.usda.gov/download-datasets/", "inputs": [{"ingredient": "chocolate amargo em barra para derreter, 70 % de cacau, sem recheio", "edible_grams": 200, "fdc_id": 170273, "fdc_description": "Chocolate, dark, 70-85% cacao solids", "per_100g": {"calories": 598, "protein_g": 7.79, "carbs_g": 45.9, "fat_g": 42.6, "saturated_fat_g": 24.5, "fiber_g": 10.9, "sugar_g": 24.0, "sodium_mg": 20.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170273/nutrients"}, {"ingredient": "creme de leite líquido pasteurizado para bater, 36 % de gordura", "edible_grams": 100, "fdc_id": 170859, "fdc_description": "Cream, fluid, heavy whipping", "per_100g": {"calories": 340, "protein_g": 2.84, "carbs_g": 2.84, "fat_g": 36.1, "saturated_fat_g": 23.0, "fiber_g": 0.0, "sugar_g": 2.92, "sodium_mg": 27.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170859/nutrients"}, {"ingredient": "manteiga sem sal", "edible_grams": 20, "fdc_id": 173430, "fdc_description": "Butter, without salt", "per_100g": {"calories": 717, "protein_g": 0.85, "carbs_g": 0.06, "fat_g": 81.1, "saturated_fat_g": 50.5, "fiber_g": 0.0, "sugar_g": 0.06, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"ingredient": "cacau natural puro em pó sem açúcar, para cobertura", "edible_grams": 10, "fdc_id": 169593, "fdc_description": "Cocoa, dry powder, unsweetened", "per_100g": {"calories": 228, "protein_g": 19.6, "carbs_g": 57.9, "fat_g": 13.7, "saturated_fat_g": 8.07, "fiber_g": 37.0, "sugar_g": 1.75, "sodium_mg": 21.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169593/nutrients"}], "serving_size": "Uma trufa; 20 unidades propostas", "method": "Soma dos gramas multiplicados pelos valores USDA por 100 g, dividida por 20. Quatro alimentos exatos e oito nutrientes informados em todos; dados ausentes nunca inventados.", "note": "Estimativa a confirmar, não análise nem teste na cozinha. 330 g é peso inicial, não rendimento final medido. Chocolate USDA genérico com 70–85 % de cacau, não análise de uma barra específica de 70 %. Creme para bater e manteiga genéricos; marca, gordura e água variam. Inclui todos os 10 g de cacau de cobertura; se sobrar, pese o aderido antes de confirmar nutrição. Não inventa perdas por evaporação, resíduos em utensílios ou absorção de cacau. Exclui casquinha de chocolate, álcool, açúcar extra e acompanhamentos."}, "image_url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "gallery": [{"url": "/recetas/recetas-de-trufas-de-chocolate/portada.webp", "alt": "Vinte pequenas trufas de chocolate amargo ligeiramente irregulares com fina camada de cacau marrom fosco, sem enfeites ou casquinha de chocolate"}], "published": false, "editorial_status": "draft", "keywords": ["trufas de chocolate", "ganache com cacau", "trufas sem álcool adicionado"], "notes": "Proposta de trufas de ganache com chocolate amargo, creme de leite, manteiga e fina camada de cacau, sem casquinha de chocolate nem álcool adicionado. Escolha barra lisa para derreter com 70 % de cacau; USDA representa o intervalo genérico 70–85 %, não análise da marca ou percentual exato. Creme deve ser líquido pasteurizado para bater com 36 % de gordura, não creme azedo nem cobertura vegetal; a ficha USDA é genérica e marcas variam. Contém leite; confira chocolate, cacau e lácteos, incluindo soja e traços de castanhas ou outros alérgenos. Não se garantem ausência de glúten, adequação para alergias ou versão vegana. Mudar chocolate, percentual de cacau, creme ou manteiga modifica firmeza e nutrição; ajuste e recalcule. Todo o cacau pesado é estimado como incluído; se ficar no prato, meça o aderido antes da confirmação, sem inventar absorção ou perdas. Sem açúcar, baunilha, licor, castanhas ou acompanhamentos extras. Use utensílios secos, manuseie creme quente com cuidado e evite água na ganache. Refrigere a 4 °C ou menos dentro de 2 horas, ou 1 hora acima de 32 °C; conte o tempo acumulado fora e não deixe creme ou ganache morna esperando. Não apresentado como estável à temperatura ambiente. As 24 horas propostas são critério de qualidade não testado, não conservação validada. Não se afirma teste na cozinha nem benefício à saúde.", "seo": {"title": "Trufas de chocolate amargo com cacau, passo a passo", "description": "Ganache de chocolate, creme de leite e manteiga: quantidades para vinte trufas propostas, dois períodos de frio, fina camada de cacau e conservação.", "image_alt": "Vinte pequenas trufas de chocolate amargo ligeiramente irregulares com fina camada de cacau marrom fosco, sem enfeites ou casquinha de chocolate", "image_variants": ["/recetas/recetas-de-trufas-de-chocolate/portada-1x1.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-4x3.webp", "/recetas/recetas-de-trufas-de-chocolate/portada-16x9.webp"], "faq": [{"q": "Posso usar chocolate ao leite, branco ou gotas?", "a": "Não como troca direta. A proposta usa barra lisa de chocolate amargo com 70 % de cacau; reveja a proporção com creme e manteiga ao mudar chocolate. Gotas podem conter ingredientes que alteram o derretimento. O cálculo USDA é genérico de 70–85 %, não análise da marca escolhida."}, {"q": "O que fazer se a ganache estiver mole ou dura demais?", "a": "Refrigere mais a ganache mole até poder porcionar e some o tempo real. Se muito dura, deixe amolecer brevemente antes de modelar, respeitando limites de conservação. Confira marca, gordura e emulsão; não improvise adições não pesadas nem afirme que essa textura foi testada. Conte as pausas extras."}, {"q": "Quanto tempo demora e como guardar?", "a": "Propõem-se 202 minutos com preparo, aquecimento, repouso, dois períodos de refrigeração, modelagem e serviço. Some os tempos reais adicionais. Mantenha a 4 °C ou menos e refrigere dentro de 2 horas, ou 1 hora acima de 32 °C. Consumir em 24 horas é proposta de qualidade não testada, não validade comprovada; não se garante armazenamento à temperatura ambiente."}]}, "content_html": "<p>Trufas de ganache propostas com chocolate amargo, creme de leite pasteurizado, manteiga e cacau natural. São propostas 20 unidades individuais e 202 minutos completos, incluindo os dois períodos de refrigeração; quantidades, firmeza e rendimento aguardam confirmação na cozinha.</p><p>Proposta de trufas de ganache com chocolate amargo, creme de leite, manteiga e fina camada de cacau, sem casquinha de chocolate nem álcool adicionado. Escolha barra lisa para derreter com 70 % de cacau; USDA representa o intervalo genérico 70–85 %, não análise da marca ou percentual exato. Creme deve ser líquido pasteurizado para bater com 36 % de gordura, não creme azedo nem cobertura vegetal; a ficha USDA é genérica e marcas variam. Contém leite; confira chocolate, cacau e lácteos, incluindo soja e traços de castanhas ou outros alérgenos. Não se garantem ausência de glúten, adequação para alergias ou versão vegana. Mudar chocolate, percentual de cacau, creme ou manteiga modifica firmeza e nutrição; ajuste e recalcule. Todo o cacau pesado é estimado como incluído; se ficar no prato, meça o aderido antes da confirmação, sem inventar absorção ou perdas. Sem açúcar, baunilha, licor, castanhas ou acompanhamentos extras. Use utensílios secos, manuseie creme quente com cuidado e evite água na ganache. Refrigere a 4 °C ou menos dentro de 2 horas, ou 1 hora acima de 32 °C; conte o tempo acumulado fora e não deixe creme ou ganache morna esperando. Não apresentado como estável à temperatura ambiente. As 24 horas propostas são critério de qualidade não testado, não conservação validada. Não se afirma teste na cozinha nem benefício à saúde.</p>"}]$records$::jsonb;
 b constant jsonb := $before${"id": "0f9407eb-d658-433d-9bff-477f17ab273f", "recipe_group_id": "b5dc3c62-05ba-4ce6-8748-39570d2271a9", "slug": "recetas-de-trufas-de-chocolate", "public_path": "/recetas-de-trufas-de-chocolate", "source_url": "https://manualdecocina.com/recetas-de-trufas-de-chocolate/", "created_at": "2026-09-23 20:50:30.015432+00", "published_at": "2026-09-23 20:50:30.015432+00", "expected_row_md5": "90eb0c876303618e78a3bc5ac61f782b"}$before$::jsonb;
 g constant uuid := 'b5dc3c62-05ba-4ce6-8748-39570d2271a9';
 outside_checksum text;
 es_count int;
 n int;
BEGIN
 IF current_setting('manualdecocina.batch04_gate',true) IS DISTINCT FROM 'ready15_deployed' THEN
  RAISE EXCEPTION 'Full15recipe lote04 publication/deployment gate not supplied';
 END IF;
 PERFORM id FROM public.recipes WHERE recipe_group_id=g ORDER BY id FOR UPDATE;
 IF jsonb_array_length(j)<>7 OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(j)x)<>7
  OR (SELECT count(DISTINCT x->>'language') FROM jsonb_array_elements(j)x)<>7
  OR (SELECT count(DISTINCT x->>'public_path') FROM jsonb_array_elements(j)x)<>7 THEN
  RAISE EXCEPTION 'Invalid chocolate_truffles payload';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND
   (r.recipe_group_id<>g OR r.language<>'es' OR r.slug<>b->>'slug' OR r.public_path<>b->>'public_path'
    OR r.source_url IS DISTINCT FROM b->>'source_url' OR r.created_at<>(b->>'created_at')::timestamptz
    OR r.published_at IS DISTINCT FROM (b->>'published_at')::timestamptz)) THEN
  RAISE EXCEPTION 'Historical identity/date divergence before idempotent or initial publication';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(j)x WHERE (x->>'recipe_group_id')::uuid<>g
    OR x->>'language' NOT IN ('es','de','en','fr','it','ja','pt')) THEN
  RAISE EXCEPTION 'Unexpected group or language in publication payload';
 END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)=7
  AND NOT EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.recipes,j)x LEFT JOIN public.recipes r ON r.id=x.id
    WHERE r.id IS NULL OR NOT r.published OR r.editorial_status<>'published' OR r.recipe_group_id<>x.recipe_group_id
      OR r.language<>x.language OR r.slug<>x.slug OR r.public_path<>x.public_path OR r.title IS DISTINCT FROM x.title OR r.excerpt IS DISTINCT FROM x.excerpt OR r.summary IS DISTINCT FROM x.summary OR r.ingredients IS DISTINCT FROM x.ingredients OR r.steps IS DISTINCT FROM x.steps OR r.category IS DISTINCT FROM x.category OR r.prep_time_minutes IS DISTINCT FROM x.prep_time_minutes OR r.cook_time_minutes IS DISTINCT FROM x.cook_time_minutes OR r.total_time_minutes IS DISTINCT FROM x.total_time_minutes OR r.servings IS DISTINCT FROM x.servings OR r.image_url IS DISTINCT FROM x.image_url OR r.content_html IS DISTINCT FROM x.content_html OR r.notes IS DISTINCT FROM x.notes OR r.difficulty IS DISTINCT FROM x.difficulty OR r.course IS DISTINCT FROM x.course OR r.cuisine IS DISTINCT FROM x.cuisine OR r.keywords IS DISTINCT FROM x.keywords OR r.nutrition IS DISTINCT FROM x.nutrition OR r.gallery IS DISTINCT FROM x.gallery OR r.seo IS DISTINCT FROM x.seo OR r.source_url IS DISTINCT FROM x.source_url) THEN
  RAISE NOTICE 'Chocolate truffles already matches7/7; no mutation'; RETURN;
 END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)<>1
  OR NOT EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND r.recipe_group_id=g
    AND r.language='es' AND NOT r.published AND md5(to_jsonb(r)::text)=b->>'expected_row_md5') THEN
  RAISE EXCEPTION 'Reserved chocolate_truffles state changed; reconcile before retry';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_populate_recordset(NULL::public.recipes,j)x
  ON r.id=x.id OR r.public_path=x.public_path OR (r.language=x.language AND r.slug=x.slug)
  WHERE r.id<>x.id OR r.recipe_group_id<>x.recipe_group_id OR r.language<>x.language) THEN
  RAISE EXCEPTION 'Chocolate truffles recipe identity/route collision';
 END IF;
 IF EXISTS(SELECT 1 FROM public.content_pages c JOIN jsonb_populate_recordset(NULL::public.recipes,j)x
  ON c.public_path=x.public_path OR (c.language=x.language AND c.slug=x.slug)) THEN
  RAISE EXCEPTION 'Chocolate truffles content_page route collision';
 END IF;
 SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) INTO outside_checksum
  FROM public.recipes r WHERE r.recipe_group_id<>g;
 SELECT count(*) INTO es_count FROM public.recipes WHERE language='es' AND published;
 UPDATE public.recipes r SET title=x.title, excerpt=x.excerpt, summary=x.summary, ingredients=x.ingredients, steps=x.steps, category=x.category, prep_time_minutes=x.prep_time_minutes, cook_time_minutes=x.cook_time_minutes, total_time_minutes=x.total_time_minutes, servings=x.servings, image_url=x.image_url, content_html=x.content_html, notes=x.notes, difficulty=x.difficulty, course=x.course, cuisine=x.cuisine, keywords=x.keywords, nutrition=x.nutrition, gallery=x.gallery, seo=x.seo,editorial_status='published',ready_at=now(),published=true
  FROM jsonb_populate_recordset(NULL::public.recipes,j)x WHERE r.id=x.id AND x.language='es';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Expected1ES update, got%',n; END IF;
 INSERT INTO public.recipes(id,recipe_group_id,language,slug,public_path,source_url,title,excerpt,summary,ingredients,steps,category,prep_time_minutes,cook_time_minutes,total_time_minutes,servings,image_url,content_html,notes,difficulty,course,cuisine,keywords,nutrition,gallery,seo,editorial_status,ready_at,published) SELECT x.id,x.recipe_group_id,x.language,x.slug,x.public_path,x.source_url,x.title,x.excerpt,x.summary,x.ingredients,x.steps,x.category,x.prep_time_minutes,x.cook_time_minutes,x.total_time_minutes,x.servings,x.image_url,x.content_html,x.notes,x.difficulty,x.course,x.cuisine,x.keywords,x.nutrition,x.gallery,x.seo,'published',now(),true FROM jsonb_populate_recordset(NULL::public.recipes,j)x WHERE x.language<>'es';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>6 THEN RAISE EXCEPTION 'Expected6translations, got%',n; END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)<>7
  OR (SELECT count(DISTINCT language) FROM public.recipes WHERE recipe_group_id=g AND published AND editorial_status='published')<>7
  OR EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.recipes,j)x LEFT JOIN public.recipes r ON r.id=x.id
    WHERE r.id IS NULL OR r.recipe_group_id<>x.recipe_group_id OR r.language<>x.language
      OR r.slug<>x.slug OR r.public_path<>x.public_path OR NOT r.published OR r.title IS DISTINCT FROM x.title OR r.excerpt IS DISTINCT FROM x.excerpt OR r.summary IS DISTINCT FROM x.summary OR r.ingredients IS DISTINCT FROM x.ingredients OR r.steps IS DISTINCT FROM x.steps OR r.category IS DISTINCT FROM x.category OR r.prep_time_minutes IS DISTINCT FROM x.prep_time_minutes OR r.cook_time_minutes IS DISTINCT FROM x.cook_time_minutes OR r.total_time_minutes IS DISTINCT FROM x.total_time_minutes OR r.servings IS DISTINCT FROM x.servings OR r.image_url IS DISTINCT FROM x.image_url OR r.content_html IS DISTINCT FROM x.content_html OR r.notes IS DISTINCT FROM x.notes OR r.difficulty IS DISTINCT FROM x.difficulty OR r.course IS DISTINCT FROM x.course OR r.cuisine IS DISTINCT FROM x.cuisine OR r.keywords IS DISTINCT FROM x.keywords OR r.nutrition IS DISTINCT FROM x.nutrition OR r.gallery IS DISTINCT FROM x.gallery OR r.seo IS DISTINCT FROM x.seo OR r.source_url IS DISTINCT FROM x.source_url) THEN
  RAISE EXCEPTION 'Chocolate truffles7/7 final content verification failed';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND
   (r.slug<>b->>'slug' OR r.public_path<>b->>'public_path' OR r.source_url IS DISTINCT FROM b->>'source_url'
    OR r.created_at<>(b->>'created_at')::timestamptz OR r.published_at IS DISTINCT FROM (b->>'published_at')::timestamptz)) THEN
  RAISE EXCEPTION 'Chocolate truffles historical identity/date preservation failed';
 END IF;
 IF outside_checksum IS DISTINCT FROM(SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) FROM public.recipes r WHERE r.recipe_group_id<>g)
  OR (SELECT count(*) FROM public.recipes WHERE language='es' AND published)<>es_count+1 THEN
  RAISE EXCEPTION 'Unexpected change outside chocolate_truffles group';
 END IF;
 RAISE NOTICE 'Chocolate truffles verified7/7 within surrounding atomic lote04 transaction';
END
$chocolate_truffles$;
